local config = {
  ui_story_5060_50600101_1_dialog_content = "¡Un concurso de fotografía en plena zona comercial, y el gran premio es unas vacaciones en el extranjero para dos!",
  ui_story_5060_50600101_2_dialog_content = "Con eso, podría irme de escapada romántica con <color=#FFB400>Kobayashi</color>!",
  ui_story_5060_50600101_3_dialog_content = "Y with the scenery",
  ui_story_5060_50600101_4_dialog_content = "¡Oye, Tohru! ¿No dijiste que íbamos a volver para recolectar algunos ingredientes exóticos de comida?",
  ui_story_5060_50600101_5_dialog_content = "¿Por qué sigues insistiendo en eso, Elma? No te preocupes, podemos reunir todos los ingredientes que necesitamos mientras estamos fuera tomando fotos!",
  ui_story_5060_50600101_6_dialog_content = "Bueno, no importa. No tenemos tiempo para discutir sobre esto. Por aquí, ¡todos!",
  ui_story_5060_50600101_7_dialog_content = "Activando la <color=#FFB400>Puerta de Teletransportación Mundial</color>—",
  ui_story_5060_50600101_8_dialog_content = "¡Muy bien, todos, prepárense para ver finalmente nuestra ciudad natal!",
  ui_story_5060_50600101_9_dialog_content = "¿Eh? Espera...",
  ui_story_5060_50600101_10_dialog_content = "<size=50>¿Qué es este lugar?!</size>",
  ui_story_5060_50600101_11_dialog_content = "¡Activando la Puerta de Teletransportación Mundial! ¡Hrrrng—! ¡Vamos, actívate!",
  ui_story_5060_50600101_12_dialog_content = "Extraño, el portal no se enciende en absoluto.",
  ui_story_5060_50600101_13_dialog_content = "Oh, esto es malo... ¿Kanna y Elma también están atrapados aquí sin forma de regresar?",
  ui_story_5060_50600101_14_dialog_content = "Está bien, solo cálmate y observa el entorno... Hay algunas cosas en este mundo que puedo reconocer.",
  ui_story_5060_50600101_15_dialog_content = "No es muy diferente del mundo de Kobayashi. Por ejemplo, aquí también hay tiendas de conveniencia y transporte público...",
  ui_story_5060_50600101_16_dialog_content = "Bueno, me voy con esta muñeca mecánica.",
  ui_story_5060_50600101_17_dialog_content = "¡Su gusto es impecable, señora! ¡A su hija le encantará este regalo lindo y obediente!",
  ui_story_5060_50600101_18_dialog_content = "Por favor, envuélvalo rápido. Necesito tomar el dirigible hacia el Shuttle Hub.",
  ui_story_5060_50600101_19_dialog_content = "¡Considérelo hecho, señora! ¡Muchas gracias por comprar con nosotros!",
  ui_story_5060_50600101_20_dialog_content = "¡Tú! Perturbar el orden de las calles con <color=#FFB400>Luminatics</color> está estrictamente prohibido aquí.",
  ui_story_5060_50600101_21_dialog_content = "¡Oye, estoy hablando de ti! ¡El <color=#FFB400>demi-humano</color> jugando con fuego allí! ¡Detén tu espectáculo callejero! ¡Ahora mismo!",
  ui_story_5060_50600101_22_dialog_content = "¡Fue mi culpa! ¡Lo s checked. in: lla chapelle>< 6 (~! a! Lo little tikes! ¡Lo siento! Me voy ahora... ¡Ay, eso duele,!",
  ui_story_5060_50600101_23_dialog_content = "¿Cómo es que el Dios de la Luz eligió bendecir a alborotadores como tú con Luminatics...",
  ui_story_5060_50600101_24_dialog_content = "¡Oye! ¿Qué estás mirando? ¡Paso atrás! ¡No bloquees el camino!",
  ui_story_5060_50600101_25_dialog_content = "......",
  ui_story_5060_50600101_26_dialog_content = "¿Qué está pasando? ¿Los demi-humanos están causando problemas de nuevo? Aléjense de ellos, todos...",
  ui_story_5060_50600101_27_dialog_content = "Eh... También hay razas <color=#FFB400>semihumanas</color> similares y <color=#FFB400>magias</color> en mi tierra natal...",
  ui_story_5060_50600101_28_dialog_content = "Pero aquí, los llaman <color=#FFB400>aurorianos semihumanos</color> y <color=#FFB400>Luminatics</color>, ¿verdad?",
  ui_story_5060_50600101_29_dialog_content = "Hay algo extraño en el <color=#FFB400>maná</color> de este mundo, y me impide <color=#FFB400>volver a convertirme en un dragón</color>. Si no fuera por mis poderes limitados...",
  ui_story_5060_50600101_30_dialog_content = "¡Les daría una lección a estos altivos y arrogantes caballeros ahora mismo!",
  ui_story_5060_50600101_31_dialog_content = "Ese castillo blanco flotante allá arriba se ve bastante sospechoso. Apuesto a que es la base de operaciones de estos caballeros.",
  ui_story_5060_50600101_32_dialog_content = "Atrapado en un extraño mundo nuevo con poderes limitados y bajo las miradas cautelosas de algunos de sus habitantes...",
  ui_story_5060_50600101_33_dialog_content = "En tal situación, ¿debería usar la fuerza para intimidar a las personas a mi alrededor primero?",
  ui_story_5060_50600101_34_dialog_content = "De esa manera, puedo ganar más tiempo para reunir fuerzas y buscar a Kanna y los demás.",
  ui_story_5060_50600101_35_dialog_content = "Urgh... No, creo que necesito reponer mi energía primero. ¿Me pregunto cómo se ve el dinero en este mundo?",
  ui_story_5060_50600101_36_dialog_content = "¡Pasteles de Longzhou recién horneados! Deliciosos y ligeros en el paladar. Hola, joven dama, ¿te apetece probar?",
  ui_story_5060_50600101_37_dialog_content = "¿Un bocado? ¿Eso significa que es gratis?",
  ui_story_5060_50600101_38_dialog_content = "¡Absolutamente! Prueba primero y compra si te gusta el sabor. Incluso hacemos entregas, así que puedes enviarles a tus amigos lejanos.",
  ui_story_5060_50600101_39_dialog_content = "(Realmente necesito confirmar si podemos comer de manera segura la comida en este mundo...)",
  ui_story_5060_50600101_40_dialog_content = "¡Mmm? ¡Esto en realidad está bastante bien!",
  ui_story_5060_50600101_41_dialog_content = "to Spanish.\nText:¡Gure! ¡Impresionante!\n\nText:Wow, that's impressive!\n!\nTranslation:¡Vaya, eso es impresionante!\n\nText:Wow, that's amazing!\nTranslation:¡Gu! ¡E!",
  ui_story_5060_50600101_42_dialog_content = "Manejas esos palillos con destreza. ¿Alguna vez has estado en <color=#FFB400>Longzhou</color>?",
  ui_story_5060_50600101_43_dialog_content = "¿Eh? Para nada. ¿Dónde está este lugar llamado \"Longzhou\"?",
  ui_story_5060_50600101_44_dialog_content = "Es mi lugar de nacimiento, un continente extranjero con una cultura próspera y comida deliciosa. Mi lugar, el Restaurante Liu, se especializa en la cocina de Longzhou.",
  ui_story_5060_50600101_45_dialog_content = "(Longzhou... ¿Tiene este restaurante algo que ver con los dragones que estoy buscando?)",
  ui_story_5060_50600101_46_dialog_content = "¿Y qué es este lugar?",
  ui_story_5060_50600101_47_dialog_content = "Aquí está Baja Lumopolis, el corazón de <color=#FFB400>Astra</color>. Tenemos comerciantes de todo el continente aquí—",
  ui_story_5060_50600101_48_dialog_content = "Espera, señorita, ¿estás perdida?",
  ui_story_5060_50600101_49_dialog_content = "De cierta manera, sí. Para ser honesto, tampoco estoy seguro de lo que pasó.",
  ui_story_5060_50600101_50_dialog_content = "¿Estás sufriendo pérdida de memoria o secuestro?! ¡Si tienes problemas, estamos aquí para echarte una mano!",
  ui_story_5060_50600101_51_dialog_content = "¿Qué tal entrar para tomar una bebida caliente y descansar un poco?",
  ui_story_5060_50600101_52_dialog_content = "(La gente aquí también puede ser muy agradable...)",
  ui_story_5060_50600101_53_dialog_content = "Gracias. Me separé de mis amigos. Solo necesito encontrarlos antes de irme a casa.",
  ui_story_5060_50600101_54_dialog_content = "Hay algo que me gustaría preguntarte... Perdón, ¿puedo preguntar tu nombre?",
  ui_story_5060_50600101_55_dialog_content = "Soy el dueño y chef del Restaurante Liu. Simplemente puedes llamarme Liu.",
  ui_story_5060_50600101_56_dialog_content = "Si necesitas ayuda, señorita, ¡solo avísame!",
  ui_story_5060_50600101_57_dialog_content = "Permítame presentarme. Mi nombre es Tohru y me preguntaba... May ¿Puedo trabajar en su restaurante por un tiempo?",
  ui_story_5060_50600101_58_dialog_content = "Sé que acabamos de conocernos y todavía tengo mucho que aprender sobre este lugar... ¡Pero mis habilidades como sirvienta son de primera clase!",
  ui_story_5060_50600101_59_dialog_content = "Cocinar, limpiar y recibir a los invitados es como una segunda naturaleza para mí. ¡Estoy seguro de que puedo ser útil en tu restaurante!",
  ui_story_5060_50600101_60_dialog_content = "¡Aquí está tu pedido de Tofu Nevado! ¡Por favor, disfruta!",
  ui_story_5060_50600101_61_dialog_content = "¡Vaya, impresionante! La comida aquí se sirve muy rápido.",
  ui_story_5060_50600101_62_dialog_content = "Aquí está la última especialidad del Chef Liu: ¡Sopa Dorada de Mariscos! Por favor, ten cuidado, ¡está muy caliente!",
  ui_story_5060_50600101_63_dialog_content = "Oh, okay.",
  ui_story_5060_50600101_64_dialog_content = "Aquí tienes un nuevo par de palillos. Si tienes problemas para usarlos... ¡También tenemos cuchillos y tenedores! ¡Aquí tienes!",
  ui_story_5060_50600101_65_dialog_content = "Tohru, ¡tenemos algunos clientes!",
  ui_story_5060_50600101_66_dialog_content = "¡Entendido! ¿Listos todos? ¡Uno, dos, tres—",
  ui_story_5060_50600101_67_dialog_content = "¡Bienvenidos!",
  ui_story_5060_50600101_68_dialog_content = "Debo decir que hoy fue bastante impactante. Casi nunca veo a tantos clientes tan relajados y felices aquí.",
  ui_story_5060_50600101_69_dialog_content = "Su actuación fue realmente sobresaliente, Srta. Tohru! Este compromiso con el servicio es lo que llamarías el espíritu de sirvienta...",
  ui_story_5060_50600101_70_dialog_content = "¡Así es! ¡Este es el espíritu de la verdadera dedicación de una sirvienta!",
  ui_story_5060_50600101_71_dialog_content = "Vaya, nunca pensé que tendría la oportunidad de encontrar algo tan nuevo y emocionante a esta edad.",
  ui_story_5060_50600101_72_dialog_content = "¡Lo mismo digo! ¡He aprendido mucho de la forma en que seleccionas y preparas tus platos!",
  ui_story_5060_50600101_73_dialog_content = "Aprender a hacer nuevos platos siempre me hace preguntarme cómo será su expresión cuando se los sirva...",
  ui_story_5060_50600101_74_dialog_content = "(¡Está bien, voy a aprender un montón de recetas que a Kobayashi le podrían gustar y las probaré cuando regrese!)",
  ui_story_5060_50600101_75_dialog_content = "¡Jefe, volvimos!",
  ui_story_5060_50600101_76_dialog_content = "Me alegra ver que regresaron sanos y salvos. Entonces, ¿encontraron a algún <color=#FFB400>Aurorian con rasgos de dragón</color> que mencionó la señorita Tohru?",
  ui_story_5060_50600101_77_dialog_content = "No, no hay pistas en eso. En cuanto al nuevo negocio...",
  ui_story_5060_50600101_78_dialog_content = "¿Te refieres al servicio de entrega, verdad? No te apresures; tómate tu tiempo.",
  ui_story_5060_50600101_79_dialog_content = "El encargado del nuevo negocio renunció de nuevo, alegando que ofrecer servicios de entrega en Astra sería demasiado arriesgado.",
  ui_story_5060_50600101_80_dialog_content = "Entonces, tuvimos que conseguir a alguien más para cubrir.",
  ui_story_5060_50600101_81_dialog_content = "Entiendo. Después de todo, los <color=#FFB400>Eclipsites</color> son bastante activos. Pueden interrumpir las rutas comerciales en cualquier momento.",
  ui_story_5060_50600101_82_dialog_content = "Tal vez necesitemos contratar a profesionales como miembros de la Unión de Mensajeros para manejarlo...",
  ui_story_5060_50600101_83_dialog_content = "He querido preguntar, pero ¿los \"<color=#FFB400>Eclipsites</color>\" son algún tipo de monstruos?",
  ui_story_5060_50600101_84_dialog_content = "Cada vez que la gente los menciona, sus rostros se ponen pálidos.",
  ui_story_5060_50600101_85_dialog_content = "Tohru, ¿¡no sabes sobre los Eclipsites?!",
  ui_story_5060_50600101_86_dialog_content = "Bueno, sí vengo de un lugar realmente lejano, ya sabes.",
  ui_story_5060_50600101_87_dialog_content = "No puedo imaginar qué tan lejos necesita estar para mantenernos alejados de los Eclipsites.",
  ui_story_5060_50600101_88_dialog_content = "Los Eclipsites han sido parte de este mundo desde que nosotros, los Aurorianos, establecimos nuestra propia historia.",
  ui_story_5060_50600101_89_dialog_content = "Tienen apariencias horribles y fuerza salvaje, a menudo viajan en grupos, causando estragos en el campo.",
  ui_story_5060_50600101_90_dialog_content = "A veces, bajo el mando de líderes poderosos, incluso atacan ciudades y siembran el caos.",
  ui_story_5060_50600101_91_dialog_content = "Parece que vivir en este mundo no es tan fácil como parece.",
  ui_story_5060_50600101_92_dialog_content = "Jaja, pero todos nos hemos acostumbrado. Ánimo, y aún podemos seguir adelante.",
  ui_story_5060_50600101_93_dialog_content = "Ahora, ¡hablemos de cómo podemos ayudar a la señorita Tohru a encontrar su camino a casa!",
  ui_story_5060_50600101_94_dialog_content = "Gracias a todos. Para ser honesto, sé el camino de regreso a casa, pero me encontré con un pequeño problema...",
  ui_story_5060_50600101_95_dialog_content = "(Los niveles de <color=#793f76>maná</color> en este mundo son demasiado inestables para que el portal se active correctamente...)",
  ui_story_5060_50600101_96_dialog_content = "(En este momento, necesito encontrar un lugar donde los niveles de mana estén relativamente equilibrados, para poder probar el portal sin interferencias...)",
  ui_story_5060_50600101_97_dialog_content = "(Pero no puedo simplemente dejar a Kanna y a los demás atrapados en este mundo...)",
  ui_story_5060_50600101_98_dialog_content = "(Necesito dinero si quiero viajar y recopilar información también. No puedo seguir dependiendo de la generosidad del Sr. Liu...)",
  ui_story_5060_50600101_99_dialog_content = "¡Ahh, qué estrés! ¡Esto debe ser lo que Kobayashi siente normalmente como cabeza de nuestra casa!",
  ui_story_5060_50600101_100_dialog_content = "Jefe, ¡malas noticias! ¡El nuevo pedido de entrega no se completó una vez más!",
  ui_story_5060_50600101_101_dialog_content = "¿Cuál es la razón esta vez?",
  ui_story_5060_50600101_102_dialog_content = "Según nuestro repartidor, el cliente en Umbraton fue secuestrado por los matones del Gremio...",
  ui_story_5060_50600101_103_dialog_content = "¡¿Eh?!",
  ui_story_5060_50600101_104_dialog_content = "La última vez, el puente frente a la casa del cliente fue destruido por los Eclipsites...",
  ui_story_5060_50600101_105_dialog_content = "Y la vez anterior, el cliente desapareció en el Territorio Secreto... No hay forma de mantener nuestro negocio así.",
  ui_story_5060_50600101_106_dialog_content = "(¿Servicio de entrega? ¡Esa podría ser mi oportunidad para explorar mis alrededores y ganar dinero al mismo tiempo!)",
  ui_story_5060_50600101_107_dialog_content = "¡Sr. Liu! ¿Qué tal si me encargo del trabajo de entrega y me ocupo del resto de esos pedidos sin entregar?",
  ui_story_5060_50600101_108_dialog_content = "Mientras me tome las cosas en serio, ¡monstruos y matones no tienen oportunidad contra mí!",
  ui_story_5060_50600101_109_dialog_content = "(Esta sería la forma perfecta para ganar dinero y aprender sobre este mundo mientras busco a Kanna y los demás.)",
  ui_story_5060_50600101_110_dialog_content = "Sin embargo, señorita Tohru, debe saber que los Eclipsites vagan con frecuencia fuera de la ciudad, y nuestro restaurante no tiene un medio de transporte mejor que una motocicleta...",
  ui_story_5060_50600101_111_dialog_content = "¿No tendría más sentido buscar ayuda de mensajeros alados...",
  ui_story_5060_50600101_112_dialog_content = "Bueno, si estamos hablando de alas, ¡resulta que yo también las tengo!",
  ui_story_5060_50600101_113_dialog_content = "Poder volar es una habilidad esencial para una sirvienta profesional. Ahora mira esto... ¡Ay!",
  ui_story_5060_50600101_114_dialog_content = "L-Lo siento, parece que comí demasiado cuando llegué aquí.",
  ui_story_5060_50600101_115_dialog_content = "¡Entonces me iré ahora!",
  ui_story_5060_50600101_116_dialog_content = "Señorita Tohru, si desea evitar atención innecesaria, es mejor no abusar de esas habilidades especiales de los demi-humanos aquí...",
  ui_story_5060_50600101_117_dialog_content = "Está bien ir despacio, ¿sabes? ¡La seguridad es lo primero!",
  ui_story_5060_50600101_118_dialog_content = "Tohru ¡Buena suerte ahí fuera!",
  ui_story_5060_50600101_119_dialog_content = "¡Entendido! Me aseguraré de completar cada pedido y traer muchas opiniones positivas. ¡Solo déjamelo a mí!",
  ui_story_5060_50600101_120_dialog_content = "¡Aquí voy, Astra!",
  ui_story_5060_50600101_121_dialog_content = "¡Esta chica repartidora de Sirvienta Dragón va con todo!",
  ui_story_5060_50600201_1_dialog_content = "¡Escuchen todos! Si no entregan la <color=#FFB400>colección</color> ahora, ¡los Celestitas enfrentarán realmente la extinción!",
  ui_story_5060_50600201_2_dialog_content = "¡Es cierto! ¡Realmente se extinguirán!",
  ui_story_5060_50600201_3_dialog_content = "Bah, ¡bastardos! ¿Cómo se atreven a tomar a alguien tan indefenso como PlayerName de rehén?!",
  ui_story_5060_50600201_4_dialog_content = "¡Luchen conmigo uno a uno, cobardes!",
  ui_story_5060_50600201_5_dialog_content = "Así es, Kobayashi dice que las personas deben pelear de manera justa en un duelo.",
  ui_story_5060_50600201_6_dialog_content = "¡Peleen conmigo uno a uno, cobardes!",
  ui_story_5060_50600201_7_dialog_content = "Bien dicho, <color=#FFB400>Kanna</color>! ¿Listo para una pelea?",
  ui_story_5060_50600201_8_dialog_content = "Sí. Gracias a Tessa, mi energía está completamente recargada.",
  ui_story_5060_50600201_9_dialog_content = "Ja-",
  ui_story_5060_50600201_10_dialog_content = "Espera, ¿no acordaste una pelea uno a uno? ¿También vas a electrocutar al rehén!?",
  ui_story_5060_50600201_11_dialog_content = "¡En realidad, no me importa en absoluto!",
  ui_story_5060_50600201_12_dialog_content = "He sobrevivido aterrizajes forzosos, lluvias torrenciales, ataques psíquicos, lesiones relacionadas con llaves inglesas e incluso a tener objetos extraños insertados en mi cuerpo...",
  ui_story_5060_50600201_13_dialog_content = "Después​ Oct , Sall around . Después and friendly.",
  ui_story_5060_50600201_14_dialog_content = "¿Qué? ¿Los Caelestites siempre son tan fuera de lugar?",
  ui_story_5060_50600201_15_dialog_content = "Je. En la forma en que están ahora, no podrían hacerle ni un rasguño a ningún Caelestite. Además...",
  ui_story_5060_50600201_16_dialog_content = "Nunca robamos la <color=#FFB400>colección</color> de la que hablas. Esto debe ser algún tipo de malentendido.",
  ui_story_5060_50600201_17_dialog_content = "Así que ya déjenlo. Ustedes también tienen que comer, ¿verdad? Si seguimos así, mi comida para llevar se va a enfriar.",
  ui_story_5060_50600201_18_dialog_content = "P-Pero... ¡ustedes fueron los únicos presentes cuando esa cosa desapareció! ¿A quién más deberíamos sospechar?!",
  ui_story_5060_50600201_19_dialog_content = "O, ya sabes... podrías simplemente ofrecerte a pagar por ello.",
  ui_story_5060_50600201_20_dialog_content = "Entonces lo siento mucho—",
  ui_story_5060_50600201_21_dialog_content = "<size=45>No voy a pagar ni un solo Nightium. ¡Ni lo pienses!</size>",
  ui_story_5060_50600201_22_dialog_content = "¿Qué debemos hacer, jefe? No puedo enfrentarme a ninguno de estos tipos yo solo, y tampoco podemos simplemente retroceder así...",
  ui_story_5060_50600201_23_dialog_content = "¡Tú, inútil idiota! Claro que no podemos retroceder ahora. Esa cosa es muy importante para nuestros señores...",
  ui_story_5060_50600201_24_dialog_content = "¡Fue robado por ese auroriano semihumano que parece tener menos de diez años!",
  ui_story_5060_50600201_25_dialog_content = "¿Así que ahora le echas la culpa a una niña pequeña? Realmente no tienes vergüenza.",
  ui_story_5060_50600201_26_dialog_content = "Parece que tendré que enseñarte una lección de la manera difícil, después de todo.",
  ui_story_5060_50600201_27_dialog_content = "?",
  ui_story_5060_50600201_28_dialog_content = "No escuches a esas malas personas ni sus mentiras, Kanna.",
  ui_story_5060_50600201_29_dialog_content = "Una vez que los saquemos, compartiré una de mis piruletas contigo.",
  ui_story_5060_50600201_30_dialog_content = "Se está acercando.",
  ui_story_5060_50600201_31_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_5060_50600201_32_dialog_content = "Esta sensación... Se está acercando, sin duda alguna.",
  ui_story_5060_50600201_33_dialog_content = "<color=#e8d9bb>Buzz Buzz-</color>",
  ui_story_5060_50600201_34_dialog_content = "¡Está aquí!",
  ui_story_5060_50600201_35_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5060_50600201_36_dialog_content = "¡Eso estuvo cerca! No llego demasiado tarde, ¿verdad?!",
  ui_story_5060_50600201_37_dialog_content = "Ahora entiendo cómo se siente Kobayashi cuando trabaja hasta el límite para cumplir con los plazos del proyecto...",
  ui_story_5060_50600201_38_dialog_content = "Ejem! Solo un momento mientras confirmo la información de contacto del destinatario...",
  ui_story_5060_50600201_39_dialog_content = "¡Hola, PlayerName! Aquí tienes tu pedido, ¡por favor recuerda darnos una calificación de cinco estrellas!",
  ui_story_5060_50600201_40_dialog_content = "Además, la tienda está buscando a una niña perdida con cuernos de dragón en la cabeza, que pueda controlar la electricidad. Si tienes alguna información relevante...",
  ui_story_5060_50600201_41_dialog_content = "Tohru—! ¡Eres tú, Tohru!",
  ui_story_5060_50600201_42_dialog_content = "¿K-Kanna?!",
  ui_story_5060_50600201_43_dialog_content = "¡Te he estado buscando por todas partes! ¡No esperaba encontrarte aquí!",
  ui_story_5060_50600201_44_dialog_content = "*Abrazo, abrazo* Tohru!",
  ui_story_5060_50600201_45_dialog_content = "No tenía idea de que la amiga que buscabas fuera una dama tan hermosa, Kanna...",
  ui_story_5060_50600201_46_dialog_content = "Parece que al final ayudamos a cumplir su deseo, ¿eh?",
  ui_story_5060_50600201_47_dialog_content = "¡Muchas gracias por cuidar de Kanna!",
  ui_story_5060_50600201_48_dialog_content = "¡No lo menciones!",
  ui_story_5060_50600201_49_dialog_content = "Pero hablando de problemas, sí tenemos que poner a estos matones en su lugar.",
  ui_story_5060_50600201_50_dialog_content = "Maldita sea, ¿el idiota realmente pidió refuerzos?",
  ui_story_5060_50600201_51_dialog_content = "Mi... cabeza... da vueltas...",
  ui_story_5060_50600201_52_dialog_content = "Tch, ¡pensé que era alguien importante! ¡Resulta que es solo una sirvienta!",
  ui_story_5060_50600201_53_dialog_content = "¿¡E-Eclipsites!? ¿Quién es esta sirvienta, capaz de hacer que los Eclipsites vengan en su ayuda?",
  ui_story_5060_50600201_54_dialog_content = "¡Corre! ¡Avance táctico hacia atrás!",
  ui_story_5060_50600201_55_dialog_content = "Si tuviera que adivinar, fue la señorita Tohru quien los atrajo hasta aquí.",
  ui_story_5060_50600201_56_dialog_content = "Entonces esos son Eclipsites, ¿eh? Me han estado persiguiendo todo este tiempo, pero estaba tan preocupado por llegar tarde que apenas los noté.",
  ui_story_5060_50600201_57_dialog_content = "Pero ahora que tu pedido ha sido entregado, ¡puedo ocuparme de ellos enseguida!",
  ui_story_5060_50600201_58_dialog_content = "¿Eh? ¡Un montón de luces de diferentes colores acaban de aparecer frente a mí!",
  ui_story_5060_50600201_59_dialog_content = "Estas deben ser las estelas de luz de las que hablaba PlayerName.",
  ui_story_5060_50600201_60_dialog_content = "Si sigues ciertos senderos de luz, ¡puedes eliminar al enemigo en muy poco tiempo!",
  ui_story_5060_50600201_61_dialog_content = "Ya veo. ¿Entonces esa es la ley de este mundo?",
  ui_story_5060_50600201_62_dialog_content = "Es como un juego, ¡así que no debería ser demasiado difícil!",
  ui_story_5060_50600201_63_dialog_content = "¡Muy bien! Ahora que conozco las reglas, ¡es hora de jugar!",
  ui_story_5060_50600201_64_dialog_content = "Tohru siempre se emociona mucho cuando se trata de destruir a sus enemigos.",
  ui_story_5060_50600202_1_dialog_content = "¡Eso fue increíble, señorita Tohru! ¡No imaginé que usarías tu cola para derrotar a los Eclipsites!",
  ui_story_5060_50600202_2_dialog_content = "Si Vice estuviera aquí, ¡definitivamente querría hacerse amiga tuya!",
  ui_story_5060_50600202_3_dialog_content = "Mantener la elegancia y la compostura incluso durante la batalla es una habilidad básica para cualquier sirvienta de verdad!",
  ui_story_5060_50600202_4_dialog_content = "(Golpear a los Eclipsites en el aire con la cola... ¿realmente se puede considerar \"elegante\"? Parece que ella podría enseñarle una cosa o dos a Vice...)",
  ui_story_5060_50600202_5_dialog_content = "Permítame expresar mi gratitud una vez más. Kanna es un miembro muy preciado de mi familia.",
  ui_story_5060_50600202_6_dialog_content = "He estado tan preocupado desde que nos separamos. ¡Gracias a ambos por su ayuda!",
  ui_story_5060_50600202_7_dialog_content = "No sé si realmente merecemos todo eso...",
  ui_story_5060_50600202_8_dialog_content = "La verdad es que no hicimos mucho por Kanna. Tú eres la que llegó y salvó el día, señorita Tohru.",
  ui_story_5060_50600202_9_dialog_content = "Puedo decir que ustedes dos son buenas personas, ¿verdad? Por favor, no se preocupen, ¡solo quería agradecerles!",
  ui_story_5060_50600202_10_dialog_content = "PlayerName y Tessa son buenas personas.",
  ui_story_5060_50600202_11_dialog_content = "Me cuidaron, me dieron dulces e incluso me ayudaron a encontrarte.",
  ui_story_5060_50600202_12_dialog_content = "Pero esos otros chicos eran mala gente.",
  ui_story_5060_50600202_13_dialog_content = "De hecho, Tessa y yo estábamos en una subasta clandestina cuando nos encontramos con Kanna.",
  ui_story_5060_50600202_14_dialog_content = "No era exactamente un lugar para niños pequeños, así que fuimos a preguntar sobre su situación.",
  ui_story_5060_50600202_15_dialog_content = "Pero justo cuando nos estábamos preparando para escoltarla, un grupo de matones nos saltó encima.",
  ui_story_5060_50600202_16_dialog_content = "Esos idiotas nos acusaron de robar los tesoros que estaban a punto de exhibir, la llamada \"<color=#FFB400>colección</color>.\"",
  ui_story_5060_50600202_17_dialog_content = "Y así es como todos terminamos aquí.",
  ui_story_5060_50600202_18_dialog_content = "Kanna, ¿en serio no te comiste su tesoro?",
  ui_story_5060_50600202_19_dialog_content = "Para nada.",
  ui_story_5060_50600202_20_dialog_content = "Pero el interior de la caja del tesoro olía tan familiar... No pude evitar tocarlo...",
  ui_story_5060_50600202_21_dialog_content = "No te sientas culpable, Kanna! Esos chicos eran un montón de idiotas malos, ¡pero tú eres una buena chica!",
  ui_story_5060_50600202_22_dialog_content = "*Acurrucarse, acurrucarse* Tessa...",
  ui_story_5060_50600202_23_dialog_content = "Tu electricidad... Se siente bien...",
  ui_story_5060_50600202_24_dialog_content = "Ah... Ella se acurruca en mis brazos de nuevo.",
  ui_story_5060_50600202_25_dialog_content = "¿Q-Qué debo hacer?",
  ui_story_5060_50600202_26_dialog_content = "Lo siento, ¡ella no suele ser así! Después de todo, este es un mundo nuevo y extraño para ella, así que es normal que se sienta un poco confundida.",
  ui_story_5060_50600202_27_dialog_content = "Ahora, Kanna, eso no es educado. Si necesitas maná, puedes comer un poco del mío.",
  ui_story_5060_50600202_28_dialog_content = "Tu mana sabe mal.",
  ui_story_5060_50600202_29_dialog_content = "¿Qué? ¡Mi mana sabe perfectamente bien!",
  ui_story_5060_50600202_30_dialog_content = "Tohru... ¿Cuándo podemos ir a casa?",
  ui_story_5060_50600202_31_dialog_content = "Yo también quiero ir a casa, pero primero necesitamos encontrar un lugar donde el mana sea lo suficientemente estable como para activar el portal.",
  ui_story_5060_50600202_32_dialog_content = "Estoy triste. Extraño a Saikawa.",
  ui_story_5060_50600202_33_dialog_content = "No te preocupes, estoy seguro de que pronto encontraremos la manera de volver a ese mundo.",
  ui_story_5060_50600202_34_dialog_content = "Hablando de eso, quería preguntarte sobre eso...",
  ui_story_5060_50600202_35_dialog_content = "Lo mencionaste antes, durante nuestra lucha contra los Eclipsites hace un momento: que ustedes dos eran de otro mundo.",
  ui_story_5060_50600202_36_dialog_content = "No estabas bromeando... ¿Verdad?",
  ui_story_5060_50600202_37_dialog_content = "Aunque es cierto que sus apariencias son bastante similares a lo que conocemos como aurorianos semihumanos...",
  ui_story_5060_50600202_38_dialog_content = "Nunca he visto a alguien o algo absorber y liberar energía de la misma manera que tú lo haces.",
  ui_story_5060_50600202_39_dialog_content = "Ese puede ser tu caso, pero realmente somos dragones de otro mundo!",
  ui_story_5060_50600202_40_dialog_content = "Esto es como esos mangas.",
  ui_story_5060_50600202_41_dialog_content = "Desafortunadamente, todavía no nos hemos reconectado con la mayoría de nuestro grupo...",
  ui_story_5060_50600202_42_dialog_content = "El personaje principal del manga está en un gran problema ahora.",
  ui_story_5060_50600202_43_dialog_content = "Has estado leyendo demasiado manga, Kanna.",
  ui_story_5060_50600202_44_dialog_content = "La pelea terminó. Estoy cansado.",
  ui_story_5060_50600202_45_dialog_content = "¿Tiene prisa, señorita Tohru?",
  ui_story_5060_50600202_46_dialog_content = "Lo estoy... Pero todavía tengo suficiente tiempo para entregar mi próximo pedido.",
  ui_story_5060_50600202_47_dialog_content = "Entonces, ¿podrías contarme sobre tu mundo mientras tomas un descanso aquí?",
  ui_story_5060_50600202_48_dialog_content = "¡Parece que te mueres por saber sobre la historia de amor entre Kobayashi y yo! Estaré encantado de contarte todo al respecto!",
  ui_story_5060_50600202_49_dialog_content = "Es una larga historia, ¡así que más vale que estés preparado!",
  ui_story_5060_50600202_50_dialog_content = "Claro. Puedo comer mi almuerzo mientras lo haces, aunque estoy seguro de que ya se ha enfriado...",
  ui_story_5060_50600202_51_dialog_content = "¡Esto no es nada! ¡Solo necesita un poco de calor!",
  ui_story_5060_50600202_52_dialog_content = "¿T-Tú puedes escupir fuego?! ¡Eso es raro, incluso en nuestro mundo!",
  ui_story_5060_50600202_53_dialog_content = "¡Guau! ¡La comida está caliente de nuevo!",
  ui_story_5060_50600202_54_dialog_content = "La temperatura es justa... Debes tener un control perfecto sobre tus llamas, señorita Tohru!",
  ui_story_5060_50600202_55_dialog_content = "¡Disfruten de sus comidas mientras los entretengo a todos con mi historia!",
  ui_story_5060_50600202_56_dialog_content = "<color=#e8d9bb>Tohru comparte apasionadamente la historia de su encuentro y conexión con una joven llamada Kobayashi.</color>",
  ui_story_5060_50600202_57_dialog_content = "<color=#e8d9bb>Sin embargo, según Kanna, parece que Tohru ha incorporado muchas de sus propias imaginaciones subjetivas en la historia...</color>",
  ui_story_5060_50600202_58_dialog_content = "Oh, ya veo.",
  ui_story_5060_50600202_59_dialog_content = "Un mundo sin Eclipsites ni noches interminables, donde todos vivan en paz y orden... Realmente quiero verlo por mí mismo.",
  ui_story_5060_50600202_60_dialog_content = "Parece que también estás muy cerca de la señorita Kobayashi.",
  ui_story_5060_50600202_61_dialog_content = "Estoy seguro de que ella estará muy preocupada si no encuentras una manera de regresar a su mundo pronto.",
  ui_story_5060_50600202_62_dialog_content = "¡Así es, por eso decidí trabajar como sirvienta repartidora!",
  ui_story_5060_50600202_63_dialog_content = "De esta manera, puedo ganar dinero mientras busco a mis amigos desaparecidos. ¡Una vez que todos estemos juntos de nuevo, podemos enfocar nuestros esfuerzos en encontrar el camino a casa!",
  ui_story_5060_50600202_64_dialog_content = "Espera... Tal vez si Kobayashi me ve después de desaparecer por tres días, ella podría... Jejejeje...",
  ui_story_5060_50600202_65_dialog_content = "Sin pensamientos sucios, Tohru.",
  ui_story_5060_50600202_66_dialog_content = "Aun así, también extraño a Kobayashi. abroad,",
  ui_story_5060_50600202_67_dialog_content = "Entonces, además de encontrar a tus amigos, también necesitas encontrar un lugar especial para que tu portal funcione, ¿verdad?",
  ui_story_5060_50600202_68_dialog_content = "Si es así, te sugiero que vayas con PlayerName para ver el Gremio de Explorador Nublar.",
  ui_story_5060_50600202_69_dialog_content = "Una de las corredoras de información más profesionales en todo Astra está allí. Es posible que pueda ayudarte.",
  ui_story_5060_50600202_70_dialog_content = "¿Eh? ¿No vienes, Tessa?",
  ui_story_5060_50600202_71_dialog_content = "No olvides, vinimos aquí para un trabajo de escolta en la subasta.",
  ui_story_5060_50600202_72_dialog_content = "Ahora que hemos terminado, uno de nosotros debe informar o habremos hecho todo esto en vano.",
  ui_story_5060_50600202_73_dialog_content = "Vaya, ¿cómo pude olvidarlo casi? Entonces contaré contigo, Tessa!",
  ui_story_5060_50600202_74_dialog_content = "¡Síganme, ustedes dos! Resulta que me llevo bastante bien con el líder del Gremio Cloudrover.",
  ui_story_5060_50600202_75_dialog_content = "El Gremio de Explorador Nublar... Ese nombre me suena familiar, pero ¿dónde lo he escuchado antes...?",
  ui_story_5060_50600202_76_dialog_content = "¡¿Eh?! ¿No es ahí donde tengo que entregar mi próximo pedido?!",
  ui_story_5060_50600202_77_dialog_content = "Y la razón por la que no se entregó la última vez...",
  ui_story_5060_50600202_78_dialog_content = "Fue porque el destinatario estaba demasiado ocupado enfrentándose a un grupo de gángsters.",
  ui_story_5060_50600301_1_dialog_content = "¿Es este el mismo Gremio de Explorador Nublar?!",
  ui_story_5060_50600301_2_dialog_content = "Déjame ver su nombre una vez más... \"<color=#FFB400>Un Asistente Muy Importante</color>\"?",
  ui_story_5060_50600301_3_dialog_content = "Señora Sheol, ¡Señora Sheol! ¿Estás aquí?",
  ui_story_5060_50600301_4_dialog_content = "El gremio está tan tranquilo ahora... Espera, ¿qué es esto?!",
  ui_story_5060_50600301_5_dialog_content = "El archivador ha sido forzado. Los documentos de inteligencia y facturas están esparcidos por el suelo. ¿Podrían haber sido robados?",
  ui_story_5060_50600301_6_dialog_content = "Si es así, ¡eso significa que nuestro cliente probablemente esté en problemas!",
  ui_story_5060_50600301_7_dialog_content = "Esperaba algo así, ¡así que solo déjamelo a mí! Resulta que soy un experto en castigar a los malhechores.",
  ui_story_5060_50600301_8_dialog_content = "Pero solías ser el peor de los peores.",
  ui_story_5060_50600301_9_dialog_content = "Honestamente, Kanna, ¡no digas cosas así! ¡No es agradable!",
  ui_story_5060_50600301_10_dialog_content = "Oye, amigos, supongo que están aquí para ver a nuestro jefe, ¿verdad?",
  ui_story_5060_50600301_11_dialog_content = "Me temo que nuestro jefe ha estado ocupado con el trabajo últimamente y no puede recibir visitantes en persona. Si tiene alguna pregunta, por favor hable con nuestra nueva asistente.",
  ui_story_5060_50600301_12_dialog_content = "¿La Señora Sheol no está aquí? ¿Y también contrató a un nuevo asistente?",
  ui_story_5060_50600301_13_dialog_content = "¿, ¿pod -",
  ui_story_5060_50600301_14_dialog_content = "Si está, ¿podrías decirle que la repartidora del restaurante ha llegado con su pedido?",
  ui_story_5060_50600301_15_dialog_content = "Además, a PlayerName y a mí también nos gustaría hacer algunas preguntas a esta guild, si eso es aceptable...",
  ui_story_5060_50600301_16_dialog_content = "Ya veo. Este pedido para llevar fue ordenado por el asistente y los demás específicamente para nuestro jefe, que estaba demasiado ocupado con el trabajo.",
  ui_story_5060_50600301_17_dialog_content = "Lamentablemente, nuestra guilda está lidiando con un pequeño problema en este momento. Me temo que no tenemos tiempo para disfrutar de las delicias de su restaurante ahora mismo.",
  ui_story_5060_50600301_18_dialog_content = "Recibiré la comida para llevar en nombre de nuestro jefe y pagaré la cuenta.",
  ui_story_5060_50600301_19_dialog_content = "Ya ves, el gremio está tratando actualmente con...",
  ui_story_5060_50600301_20_dialog_content = "Debes ser el famoso PlayerName, nuestro compañero Caelestite, ¿verdad?",
  ui_story_5060_50600301_21_dialog_content = "El famoso...",
  ui_story_5060_50600301_22_dialog_content = "¿Caelestita...?",
  ui_story_5060_50600301_23_dialog_content = "P-Por favor no me llames así! Me estás avergonzando frente a mis nuevos amigos!",
  ui_story_5060_50600301_24_dialog_content = "Entiendo. Lo siento si esto está causando alguna molestia.",
  ui_story_5060_50600301_25_dialog_content = "Resulta que tenemos algunos asuntos internos que discutir contigo, PlayerName. ¿Te importaría unirte a nosotros afuera?",
  ui_story_5060_50600301_26_dialog_content = "Ustedes dos encantadoras damas, por favor esperen un momento en el salón de recepción.",
  ui_story_5060_50600301_27_dialog_content = "Vaya, ¿tenemos que esperar?",
  ui_story_5060_50600301_28_dialog_content = "Me pregunto si a los dos les gustaría disfrutar de nuestros productos especiales mientras esperan?",
  ui_story_5060_50600301_29_dialog_content = "Nuestro Gremio de Explorador Nublar ha recolectado varios tesoros exóticos de las Ciudades Subterráneas de Illumina, el Desierto Rediesel, la Corte del Norte y más...",
  ui_story_5060_50600301_30_dialog_content = "Vaya, tantos lindos y bonitos—",
  ui_story_5060_50600301_31_dialog_content = "Si encuentras algún tesoro que te llame la atención, estaremos más que dispuestos a ofrecértelo con un descuento, como muestra de nuestra amistad.",
  ui_story_5060_50600301_32_dialog_content = "Pero no tengo dinero.",
  ui_story_5060_50600301_33_dialog_content = "¡Ejem! Sabes, Kanna, ya me pagaron por mi trabajo. No estaría mal gastar un poco de eso...",
  ui_story_5060_50600301_34_dialog_content = "¿En serio? ¡Eres el mejor, Tohru!",
  ui_story_5060_50600301_35_dialog_content = "Entonces, ¿qué pasó exactamente con el gremio? Parece bastante grave.",
  ui_story_5060_50600301_36_dialog_content = "¿Te has enterado de la emocionante subasta clandestina en Umbraton y Lower Lumopolis recientemente?",
  ui_story_5060_50600301_37_dialog_content = "Como uno de los gremios más reconocidos de Astra, nuestro Gremio de Explorador Nublar también resulta ser un gran patrocinador de la subasta.",
  ui_story_5060_50600301_38_dialog_content = "Pero últimamente, las cosas se han descontrolado en la subasta, con gente insistiendo en que sus artículos exhibidos fueron robados.",
  ui_story_5060_50600301_39_dialog_content = "Están haciendo acusaciones infundadas y provocando peleas con otros asistentes, causando un caos total.",
  ui_story_5060_50600301_40_dialog_content = "La Señora Sheol está trabajando duro para resolver este asunto.",
  ui_story_5060_50600301_41_dialog_content = "Oh... Eso es...",
  ui_story_5060_50600301_42_dialog_content = "Esos alborotadores incluso irrumpieron en nuestro Gremio, causando el alboroto que acabas de presenciar.",
  ui_story_5060_50600301_43_dialog_content = "Hemos puesto tanto esfuerzo en transportar las piezas de la subasta, y ahora han desaparecido. ¿No debería ser responsable el Gremio Cloudrover?",
  ui_story_5060_50600301_44_dialog_content = "La colección fue robada bajo tu vigilancia, ¡así que tú pagas por ello!",
  ui_story_5060_50600301_45_dialog_content = "De lo contrario, ¡el señor de Lumopolis que nos contrató no te perdonará!",
  ui_story_5060_50600301_46_dialog_content = "Así es. Sugiero que todos ustedes, miembros del Gremio de Explorador Nublar, cooperen con nuestra investigación y no vayan en contra de nuestro señor.",
  ui_story_5060_50600301_47_dialog_content = "Entonces, incluso los soldados privados que trabajan para los nobles de Lumopolis también están involucrados, ¿eh? Qué asco.",
  ui_story_5060_50600301_48_dialog_content = "Las colecciones raras a menudo son reservadas por nobles influyentes; es una rutina común.",
  ui_story_5060_50600301_49_dialog_content = "Para ellos, pujar es simplemente una demostración de su poder y estatus.",
  ui_story_5060_50600301_50_dialog_content = "Sin embargo, lo que podría irritarles ligeramente se convertiría en una verdadera carga para nosotros, los comerciantes.",
  ui_story_5060_50600301_51_dialog_content = "Si no fuera por la previsión del jefe de traer un asistente capaz para lidiar con ellos, estaríamos abrumados.",
  ui_story_5060_50600301_52_dialog_content = "Entonces, ¿cómo planea la Señora Sheol lidiar con esto?",
  ui_story_5060_50600301_53_dialog_content = "Sospecha que estos objetos desaparecieron de las cajas mucho antes de llegar al lugar de la subasta.",
  ui_story_5060_50600301_54_dialog_content = "Es por eso que ella espera que tú, que compartes un vínculo cercano con ella, puedas echar una mano en este asunto.",
  ui_story_5060_50600301_55_dialog_content = "Intenta usar tus habilidades psíquicas como Caelestite para ver si puedes encontrar alguna pista sobre los objetos perdidos y confirmar sus sospechas.",
  ui_story_5060_50600301_56_dialog_content = "...Entonces lamento decepcionarlos a todos...",
  ui_story_5060_50600301_57_dialog_content = "De hecho, fui uno de los invitados que fue abordado en la subasta anterior...",
  ui_story_5060_50600301_58_dialog_content = "Para aclarar las cosas, intenté usar mis habilidades psíquicas para buscar pistas, pero no encontré nada.",
  ui_story_5060_50600301_59_dialog_content = "Me temo que la caja que contiene la colección realmente está vacía.",
  ui_story_5060_50600301_60_dialog_content = "Qué pena. Parece que tendremos que contar con el asistente para mantener ocupada a esa gente.",
  ui_story_5060_50600301_61_dialog_content = "Si nos puedes ayudar a resolver esto, nuestra jefa seguramente expresará su gratitud.",
  ui_story_5060_50600301_62_dialog_content = "La gratitud de Sheol, ¿eh...",
  ui_story_5060_50600301_63_dialog_content = "Fuiste de gran ayuda para mí, amigo mío...",
  ui_story_5060_50600301_64_dialog_content = "Parece que necesito subirte un par de niveles en mis estimaciones.",
  ui_story_5060_50600301_65_dialog_content = "Ahora dime, ¿cómo debo compensarte adecuadamente por tus problemas...?",
  ui_story_5060_50600301_66_dialog_content = "...N-No me importa ayudar, ¡pero paso de la gratitud de Lady Sheol! ¡Realmente no puedo manejar más de eso!",
  ui_story_5060_50600301_67_dialog_content = "Hmm, creo que voy a pasar.",
  ui_story_5060_50600301_68_dialog_content = "¿Eh? ¿De quién es esa voz?",
  ui_story_5060_50600301_69_dialog_content = "Translation: *\n\nText, the translation and \", in - – about the, [/﻿,® the, mar,, a street... - - - - AlertHTP\n\n   of, a - the GI,000",
  ui_story_5060_50600301_70_dialog_content = "(¡Espera, esta señora súper madura es la asistente de la que hablábamos antes?!)",
  ui_story_5060_50600301_71_dialog_content = "(Sí, inusual, pero con ella, pero parece mucho más amigable.",
  ui_story_5060_50600301_72_dialog_content = "¡Oh, tú también estás aquí? De verdad lo siento, pero aún tengo un trabajo que hacer, ¡sabes!",
  ui_story_5060_50600301_73_dialog_content = "Esos matones están realmente dedicados a sus trabajos. He estado haciendo todo lo posible para persuadirlos, pero aún no ceden...",
  ui_story_5060_50600301_74_dialog_content = "¡Oigan, amigos, manténganse alerta! Esta chica no es una Auroriana común y corriente... ¡Hay algo realmente extraño en ella!",
  ui_story_5060_50600301_75_dialog_content = "Sé que parezco un poco diferente, ¡pero eso no es motivo para ser tan cauteloso!",
  ui_story_5060_50600301_76_dialog_content = "¡Estoy más que feliz de hablar y encontrar una solución a este problema!",
  ui_story_5060_50600301_77_dialog_content = "¡No te dejes engañar por su apariencia! ¡Hmph, ella cree que puede halagarnos y simplemente nos iremos? ¡No es tan fácil!",
  ui_story_5060_50600301_78_dialog_content = "Al final del día, ella es solo una chica semi-humana, ni siquiera digna de ser sirvienta de los señores de Uptown.",
  ui_story_5060_50600301_79_dialog_content = "Vamos todos a unirnos contra ella, amigos. ¡Seguro que la derribaremos y luego la usaremos como moneda de cambio!",
  ui_story_5060_50600301_80_dialog_content = "¿Oh? ¡Qué miedo!",
  ui_story_5060_50600301_81_dialog_content = "Déjala en paz, malditos idiotas—",
  ui_story_5060_50600301_82_dialog_content = "¡Vaya, un verdadero caballero vino a rescatarme! ¡Estoy muy agradecida!",
  ui_story_5060_50600301_83_dialog_content = "Pero como el <color=#FFB400>Asistente Muy Importante</color> del gremio, también puedo ser bastante útil en una pelea.",
  ui_story_5060_50600302_1_dialog_content = "Sigasanormalmente to Spanish: Siguen viniendoendo. ¿Estás  to Spanish: Siguen vini, and at January, aters and the additional cost'",
  ui_story_5060_50600302_2_dialog_content = "¡Estoy perfectamente bien! Si acaso, debe ser difícil para ti apoyarme mientras te proteges a ti mismo, PlayerName.",
  ui_story_5060_50600302_3_dialog_content = "E-Espera, ¿dónde aprendiste mi nombre?",
  ui_story_5060_50600302_4_dialog_content = "De Lady Sheol, ¡por supuesto! Ella me contó mucho sobre ti...",
  ui_story_5060_50600302_5_dialog_content = "¡Maldiciones! El trabajo de los señores no está terminado. Levanten sus traseros, ¡no se atrevan a subestimarnos!",
  ui_story_5060_50600302_6_dialog_content = "Ojalá todos pudieran leer la situación y actuar adecuadamente.",
  ui_story_5060_50600302_7_dialog_content = "Todos ustedes se están pasando de la raya... Lo que significa que tendré que tomar las cosas un poco más en serio... Niños buenos, recuerden apartar la mirada!",
  ui_story_5060_50600302_8_dialog_content = "¡O-Oye! ¿Por qué me tapas los ojos?",
  ui_story_5060_50600302_9_dialog_content = "¿Qué?... ¿Q-q-qué es esta criatura?! Ugh...",
  ui_story_5060_50600302_10_dialog_content = "Uf... Puedes mirar ahora. Estos chicos deberían estar un poco más tranquilos ahora.",
  ui_story_5060_50600302_11_dialog_content = "(¿Eh? Guau... ¿Qué demonios hizo Lucoa a esos matones..?)",
  ui_story_5060_50600302_12_dialog_content = "(Parece que los acaban de lanzar a un pozo lleno de Eclipsites de alto nivel...)",
  ui_story_5060_50600302_13_dialog_content = "Déjame sentir alrededor...",
  ui_story_5060_50600302_14_dialog_content = "¿Es esto... una pluma...?",
  ui_story_5060_50600302_15_dialog_content = "Ah—¡Dije que no miraras!",
  ui_story_5060_50600302_16_dialog_content = "¡L-Lo siento! Solo tenía curiosidad acerca de tu poder, eso es todo...",
  ui_story_5060_50600302_17_dialog_content = "¿Oh? ¿Así que tienes curiosidad por ver mi verdadera forma?",
  ui_story_5060_50600302_18_dialog_content = "Sabes, ¡eres igual de lindo que <color=#FFB400>Shouta</color> cuando lo miro de cerca!",
  ui_story_5060_50600302_19_dialog_content = "La cara que pones cuando usas tus poderes es especialmente linda. ¡Así que este es el Caelestite del que tanto he oído hablar!",
  ui_story_5060_50600302_20_dialog_content = "Qué carita tan linda... ¿Te importaría si la toco?",
  ui_story_5060_50600302_21_option_content = "¡Fuera, demonio!",
  ui_story_5060_50600302_22_dialog_content = "Aww, realmente duele. No soy un demonio en absoluto...",
  ui_story_5060_50600302_23_dialog_content = "¡Ahora soy una buena persona!",
  ui_story_5060_50600302_24_dialog_content = "¡Cualquier otra persona te habría denunciado a los Guardianes de Lumopolis hace mucho tiempo!",
  ui_story_5060_50600302_25_option_content = "P-Pero me asfixiaré...",
  ui_story_5060_50600302_26_dialog_content = "¿N-No tienes otros asuntos del gremio que atender, señorita Lucoa...?",
  ui_story_5060_50600302_27_dialog_content = "Este lugar es peligroso, después de todo. Quién sabe cuándo aparecerán esos soldados privados para investigar... Jajaja...",
  ui_story_5060_50600302_28_dialog_content = "Para ser honesto, soy menos un asistente y más un guardaespaldas que Lady Sheol contrató para este asunto.",
  ui_story_5060_50600302_29_dialog_content = "En realidad soy bastante poderoso y puedo manejar la mayoría de las situaciones.",
  ui_story_5060_50600302_30_dialog_content = "Después de todo, resulta que soy una diosa en mi tierra natal...",
  ui_story_5060_50600302_31_dialog_content = "Lu—co—a—",
  ui_story_5060_50600302_32_dialog_content = "¿Mmm? ¿Eres tú, Tohru?",
  ui_story_5060_50600302_33_dialog_content = "He estado corriendo como loco tratando de encontrar una manera de reactivar el portal...",
  ui_story_5060_50600302_34_dialog_content = "¿¡Y tú estás aquí holgazaneando?!",
  ui_story_5060_50600302_35_dialog_content = "Y llamándote a ti mismo un \"Asistente Muy Importante\"...",
  ui_story_5060_50600302_36_dialog_content = "¡Vaya! ¿Cómo descubriste mi alias en este mundo, Tohru...?",
  ui_story_5060_50600302_37_dialog_content = "Lucoa ha sido expuesto.",
  ui_story_5060_50600302_38_dialog_content = "¡Ah! ¿No me digas que eres tú quien entrega mi comida, Tohru?",
  ui_story_5060_50600302_39_dialog_content = "Una chica repartidora vestida de sirvienta... ¡Qué truco interesante!",
  ui_story_5060_50600302_40_dialog_content = "Desde que me di cuenta de lo diferente que es el mana en este mundo, he estado tratando de encontrar una manera de mejorar la capacidad de mi cuerpo para convertirlo.",
  ui_story_5060_50600302_41_dialog_content = "De esa manera, podría usar mis poderes para determinar la ubicación exacta de todos.",
  ui_story_5060_50600302_42_dialog_content = "Lamentablemente, ya que la mayoría de las personas aquí tienden a usar estos llamados \"Luminatics\" para resolver sus problemas...",
  ui_story_5060_50600302_43_dialog_content = "No he podido encontrar un niño tan talentoso como Shouta para formar un pacto temporal conmigo.",
  ui_story_5060_50600302_44_dialog_content = "Gracias a Dios nadie ha resultado herido hasta ahora.",
  ui_story_5060_50600302_45_dialog_content = "Pero no puedo decir que no estoy interesado en este Caelestite del que todos hablan. Si acaso, ¡tengo grandes esperanzas en él!",
  ui_story_5060_50600302_46_dialog_content = "Dale un descanso ya, Lucoa!",
  ui_story_5060_50600302_47_dialog_content = "¡Ejem! En cualquier caso, logramos encontrar Lucoa, lo que significa que solo necesitamos encontrar Elma y Fafnir ahora.",
  ui_story_5060_50600302_48_dialog_content = "Bueno, Lucoa? Todos dicen que este gremio es una de las mejores fuentes de información.",
  ui_story_5060_50600302_49_dialog_content = "¿Has descubierto algo sobre esos dos?",
  ui_story_5060_50600302_50_dialog_content = "He estado prestando mucha atención a todo lo relacionado con dragones o semihumanos con características similares a los dragones.",
  ui_story_5060_50600302_51_dialog_content = "Mi pista más reciente involucra la desaparición de una colección de una subasta, en lo que estoy trabajando ahora mismo.",
  ui_story_5060_50600302_52_dialog_content = "¿Eh? ¿Así que también estás investigando a esos matones? ¿Y es porque tienen algo que ver con dragones?",
  ui_story_5060_50600302_53_dialog_content = "Por supuesto. Mi intuición nunca miente, ¿sabes?",
  ui_story_5060_50600302_54_dialog_content = "Lucoa se está poniendo serio.",
  ui_story_5060_50600302_55_dialog_content = "La mayoría de esos matones trabajan para una banda de contrabando, y uno de ellos menciona accidentalmente que el objeto perdido es un tesoro oculto de un dragón.",
  ui_story_5060_50600302_56_dialog_content = "Un tesoro que solo se obtuvo después de arriesgar la muerte bajo las garras de un dragón.",
  ui_story_5060_50600302_57_dialog_content = "¿Alguno de nosotros dejó caer algo? ¿Quizás Fafnir...?",
  ui_story_5060_50600302_58_dialog_content = "Probablemente no...",
  ui_story_5060_50600302_59_dialog_content = "De lo contrario, serían maldecidos.",
  ui_story_5060_50600302_60_dialog_content = "Tienes un punto.",
  ui_story_5060_50600302_61_dialog_content = "Señorita Lucoa, me gustaría hacerte algunas preguntas, ¿está bien?",
  ui_story_5060_50600302_62_dialog_content = "Lady Sheol quería usar mis poderes para localizar la colección perdida.",
  ui_story_5060_50600302_63_dialog_content = "Pero cuando intenté usarlos en la subasta, no sé si fue falta de información o algo más...",
  ui_story_5060_50600302_64_dialog_content = "Mis poderes psíquicos no funcionaron.",
  ui_story_5060_50600302_65_dialog_content = "¿Podrías contarme más sobre esta colección desaparecida? ¿O tal vez más información sobre esta banda de contrabandistas?",
  ui_story_5060_50600302_66_dialog_content = "Sé lo que estás pensando. Como Caelestite, necesitas estar lo suficientemente familiarizado con algo para poder percibirlo con tus poderes, ¿verdad?",
  ui_story_5060_50600302_67_dialog_content = "Los contrabandistas en cuestión generalmente trabajan para las clases altas de Umbraton y Lumopolis. Se especializan en cazar criaturas grandes y buscar artefactos en ruinas.",
  ui_story_5060_50600302_68_dialog_content = "Los artículos que trajeron para exhibir esta vez fueron principalmente especímenes y pieles de criaturas raras y valiosas.",
  ui_story_5060_50600302_69_dialog_content = "Incluso podrían haber traído un espécimen vivo...",
  ui_story_5060_50600302_70_dialog_content = "Eso explicaría por qué la parte superior de esa caja se sentía tan cálida...",
  ui_story_5060_50600302_71_dialog_content = "Espera, ¿también encontraste una pista, Kanna?!",
  ui_story_5060_50600302_72_dialog_content = "Bueno, Kanna? ¿Cómo desapareció el tesoro?",
  ui_story_5060_50600302_73_dialog_content = "Probablemente... Probablemente porque le crecieron piernas y se escapó!",
  ui_story_5060_50600302_74_dialog_content = "Err...",
  ui_story_5060_50600302_75_dialog_content = "Además de manga, me pregunto si también te estoy dejando leer demasiados cuentos de hadas...",
  ui_story_5060_50600302_76_dialog_content = "...Aún nada. Incluso con la ayuda de Kanna y Lucoa, y sabiendo que es un espécimen vivo...",
  ui_story_5060_50600302_77_dialog_content = "Todavía no tengo forma de sentir dónde está.",
  ui_story_5060_50600302_78_dialog_content = "No te frustres, PlayerName. Ya has hecho mucho.",
  ui_story_5060_50600302_79_dialog_content = "Lo sé, pero no todos los días puedo ayudar a todos y al mismo tiempo ganar favores de Lady Sheol. Ojalá pudiera hacer más...",
  ui_story_5060_50600302_80_dialog_content = "Aquí viene mi oportunidad.",
  ui_story_5060_50600302_81_dialog_content = "¡Ven aquí, pequeña Caelestite! ¡Recibe un abrazo!",
  ui_story_5060_50600302_82_dialog_content = "¡Waaaah! S-S-Suéltame...!",
  ui_story_5060_50600302_83_dialog_content = "Qué tibia reacción, PlayerName.",
  ui_story_5060_50600302_84_dialog_content = "Gracias a tu influencia, tengo una comprensión mucho más amplia de este mundo. De alguna manera, es como si compartiéramos la misma mente a pesar de tener cuerpos separados.",
  ui_story_5060_50600302_85_dialog_content = "¡Permíteme transmitirte mi poder!",
  ui_story_5060_50600302_86_dialog_content = "E-Eso fue solo yo usando mis habilidades psíquicas antes! ¡Solo te estaba ayudando a ver las estelas de luz!",
  ui_story_5060_50600302_87_dialog_content = "¡Detente, o te reportaré a la Señora Sheol!",
  ui_story_5060_50600302_88_dialog_content = "¿En serio? Lady Sheol y yo somos bastante cercanos, ¿sabes? ¡Incluso me dio algo que realmente quería como adelanto de mi salario!",
  ui_story_5060_50600302_89_dialog_content = "Lamentablemente, ya que he recibido un tributo, ya no puedo hacer lo que quiera.",
  ui_story_5060_50600302_90_dialog_content = "Apúrate Tohru, o PlayerName podría morir...",
  ui_story_5060_50600302_91_dialog_content = "Ugh, sinceramente... Parece que sigues haciendo lo que quieres, Lucoa.",
  ui_story_5060_50600302_92_dialog_content = "Si tienes tanto tiempo libre, ¿por qué no me ayudas a entregar estos pedidos?!",
  ui_story_5060_50600302_93_dialog_content = "De todos modos, PlayerName, ¿estás seguro de que quieres ayudarnos?",
  ui_story_5060_50600302_94_dialog_content = "¿No tienes otros trabajos o investigaciones que hacer?",
  ui_story_5060_50600302_95_dialog_content = "¿Podemos ir juntos?",
  ui_story_5060_50600302_96_dialog_content = "No digas cosas así, Kanna. Resulta que PlayerName es alguien muy importante en este mundo.",
  ui_story_5060_50600302_97_dialog_content = "Estoy seguro de que tiene muchas cosas igual de importantes que hacer en este momento.",
  ui_story_5060_50600302_98_dialog_content = "En realidad no... Y realmente no soy tan importante, señorita Tohru. De todos modos, ¿a dónde va su próximo pedido?",
  ui_story_5060_50600302_99_dialog_content = "Déjame ver, creo que era un puesto de avanzada en un lugar llamado \"Puesto de avanzada de Illumina.\"",
  ui_story_5060_50600302_100_dialog_content = "¡Entonces eso no debería ser un problema! ¡Necesito ir allí también!",
  ui_story_5060_50600302_101_dialog_content = "Como un puesto de avanzada en las tierras fronterizas, debe haber muchos contrabandistas operando en la zona. ¡Apuesto a que encontraremos mucha información allí!",
  ui_story_5060_50600302_102_dialog_content = "¡Yay, nos toca ir en otra aventura!",
  ui_story_5060_50600302_103_dialog_content = "Para ahorrarnos tiempo, ¿por qué no volamos hacia allá?",
  ui_story_5060_50600302_104_dialog_content = "¿Eh? ¿Cómo supiste que podía convertirme en un dragón, PlayerName? No recuerdo haberte dicho eso.",
  ui_story_5060_50600302_105_dialog_content = "¿Ah?",
  ui_story_5060_50600302_106_dialog_content = "Quise decir que podemos montar en Soroz hacia el Puesto Avanzado de Illumina. ¿De qué estabas hablando, señorita Tohru?",
  ui_story_5060_50600302_107_dialog_content = "S... ¿Sor-qué?",
  ui_story_5060_50600401_1_dialog_content = "Entonces esto es Soroz, ¿PlayerName? Tu amigo es tan pequeño...",
  ui_story_5060_50600401_2_dialog_content = "¡Hola! A Soroz le molestaría mucho si lo confundes con un dirigible común y corriente.",
  ui_story_5060_50600401_3_dialog_content = "Entenderás una vez que llegues allí... Apuesto a que Soroz no es más pequeño que ningún dragón que hayas mencionado hasta ahora.",
  ui_story_5060_50600401_4_dialog_content = "¿En serio? ¡Estoy aún más emocionado de verlo!",
  ui_story_5060_50600401_5_dialog_content = "Aun así, este dirigible es demasiado pequeño para transportarnos a todos a Soroz en un solo viaje.",
  ui_story_5060_50600401_6_dialog_content = "Dijiste algo sobre poder volar, ¿verdad señorita Tohru?",
  ui_story_5060_50600401_7_dialog_content = "¡Por supuesto! Después de todo, ¡soy un dragón!",
  ui_story_5060_50600401_8_dialog_content = "¿Entonces realmente puedes volar?",
  ui_story_5060_50600401_9_dialog_content = "Quiero montar en el dirigible. Parece divertido.",
  ui_story_5060_50600401_10_dialog_content = "En ese caso, me quedaré con Kanna.",
  ui_story_5060_50600401_11_dialog_content = "¿No podrías intentar perder un poco de peso, Lucoa? No hay espacio para mi motocicleta...",
  ui_story_5060_50600401_12_dialog_content = "Oye PlayerName, ¿puedo hacerte una pregunta?",
  ui_story_5060_50600401_13_dialog_content = "Claro, ¿qué es?",
  ui_story_5060_50600401_14_dialog_content = "¿Qué son exactamente los aurorianos semihumanos?",
  ui_story_5060_50600401_15_dialog_content = "Mientras hacía entregas, vi a unos niños alados volando por el cielo.",
  ui_story_5060_50600401_16_dialog_content = "Parecían tan cómodos y libres, y se parecían mucho a nosotros en este momento.",
  ui_story_5060_50600401_17_dialog_content = "Pero la gente de Lumopolis parece considerar sus cuernos y alas como cosas malas... Aunque no entiendo realmente por qué.",
  ui_story_5060_50600401_18_dialog_content = "¿Los nobles también se metieron contigo mientras estabas en Lumopolis, señorita Tohru?",
  ui_story_5060_50600401_19_dialog_content = "Para nada. Tal vez fue por mi aura destructiva; ninguno de ellos se atrevió a acercarse a mí.",
  ui_story_5060_50600401_20_dialog_content = "Sin embargo, hicieron las cosas muy difíciles para los otros demi-humanos que trabajaban en el restaurante del Sr. Liu. No podía soportar verlos.",
  ui_story_5060_50600401_21_dialog_content = "Hay muchas razones involucradas, pero su raza y estatus social son definitivamente las más importantes.",
  ui_story_5060_50600401_22_dialog_content = "Los verdaderos semi-humanos eran incapaces de usar Luminatics, por lo que fueron exterminados hace mucho tiempo.",
  ui_story_5060_50600401_23_dialog_content = "Los aurorianos semihumanos que vemos hoy en día son descendientes de verdaderos semihumanos que se casaron con aurorianos.",
  ui_story_5060_50600401_24_dialog_content = "Para los nobles de Lumo, estas personas no deseadas no son más que una mancha en su fe y sus nobles linajes.",
  ui_story_5060_50600401_25_dialog_content = "Ugh, esto otra vez. Fe, linajes puros, bendiciones... Es por ideas como estas que vemos a los humanos como una especie tonta e inferior.",
  ui_story_5060_50600401_26_dialog_content = "Afortunadamente, los aurorianos se han vuelto cada vez más aceptantes hacia los aurorianos semihumanos en estos días. Esta tendencia también está ocurriendo entre algunos nobles de Lumopolis...",
  ui_story_5060_50600401_27_dialog_content = "Oh, parece que ya casi llegamos. Deberíamos poder ver Soroz una vez que pasemos por estas nubes.",
  ui_story_5060_50600401_28_dialog_content = "¡A todos, me gustaría que conozcan a mi amigo Soroz!",
  ui_story_5060_50600401_29_dialog_content = "Los Aurorianos de este mundo se refieren a su especie como los Colosos. Son compañeros cercanos de los Celestitas y solo pueden ser pilotados por nuestra gente.",
  ui_story_5060_50600401_30_dialog_content = "¡Vaya, es enorme! Espera, ¿Soroz es... un dragón completamente mecánico?!",
  ui_story_5060_50600401_31_dialog_content = "Un dragón robot, justo como en las películas.",
  ui_story_5060_50600401_32_dialog_content = "Algo tan único debe ser realmente bueno en combate, ¿verdad? ¿Puedo desafiarlo a una pelea ahora mismo?!",
  ui_story_5060_50600401_33_dialog_content = "Eh... Soroz nunca ha estado en una batalla...",
  ui_story_5060_50600401_34_dialog_content = "Qué pena.",
  ui_story_5060_50600401_35_dialog_content = "De todos modos, entremos.",
  ui_story_5060_50600401_36_dialog_content = "¡Guau—Tan bonito!",
  ui_story_5060_50600401_37_dialog_content = "Este lugar también—",
  ui_story_5060_50600401_38_dialog_content = "No molestes a los demás, Kanna!",
  ui_story_5060_50600401_39_dialog_content = "No solo hay mucho espacio, sino que también está completamente equipado y decorado con buen gusto. ¡Vivir aquí debe ser realmente conveniente!",
  ui_story_5060_50600401_40_dialog_content = "Advertencia: acercándose al límite de peso. Por favor, evite llevar equipaje excesivo.",
  ui_story_5060_50600401_41_dialog_content = "...¿No te lo dije, Lucoa? Realmente deberías intentar perder algo de peso.",
  ui_story_5060_50600401_42_dialog_content = "¿En serio? ¿Quieres decir que no es tu cola gordita la que nos está haciendo más pesados?",
  ui_story_5060_50600401_43_dialog_content = "No te preocupes, probablemente sea solo un fallo en el sistema. Soroz es mucho más resistente que eso.",
  ui_story_5060_50600401_44_dialog_content = "Parece que realmente confías en este gran Coloso tuyo. Debes tener una relación maravillosa con él.",
  ui_story_5060_50600401_45_dialog_content = "¡Claro! Después de todo, Soroz es uno de mis amigos más cercanos e importantes.",
  ui_story_5060_50600401_46_dialog_content = "Hace más de diez años... perdí mi hogar, así como a toda mi familia.",
  ui_story_5060_50600401_47_dialog_content = "No tuve más opción que aceptar que yo era el último Caelestite vivo en el mundo.",
  ui_story_5060_50600401_48_dialog_content = "Si no fuera por Soroz que me hizo compañía y me enseñó todo tipo de cosas, no estaría donde estoy hoy.",
  ui_story_5060_50600401_49_dialog_content = "Entiendo completamente.",
  ui_story_5060_50600401_50_dialog_content = "Mi relación con Kobayashi es exactamente igual. Como era de esperar, el amor no conoce límites, ¡ni siquiera entre especies!",
  ui_story_5060_50600401_51_dialog_content = "No estoy seguro si es EXACTAMENTE lo mismo.",
  ui_story_5060_50600401_52_dialog_content = "Entonces, verás, señorita Tohru, sé lo que se siente al llegar a un mundo nuevo y extraño, y el miedo y la desconfianza que eso conlleva.",
  ui_story_5060_50600401_53_dialog_content = "Pero gracias a la ayuda de Soroz y al apoyo de innumerables amigos...",
  ui_story_5060_50600401_54_dialog_content = "Ya no me siento tan solo e impotente en el mundo.",
  ui_story_5060_50600401_55_dialog_content = "Así que cuando vi lo desesperadamente que querías reunirte con tus amigos, mi corazón me dijo que te ayudara en todo lo que pudiera.",
  ui_story_5060_50600401_56_dialog_content = "Los amigos son nuestro tesoro más grande. No sé cuánto tiempo más estarán conectados nuestros mundos...",
  ui_story_5060_50600401_57_dialog_content = "Pero incluso si es solo por un corto tiempo, realmente espero que todos podamos ser amigos, señorita Tohru!",
  ui_story_5060_50600401_58_dialog_content = "Quiero escuchar aún más historias sobre los otros mundos a los que has ido... ¡Así como la historia de amor entre tú y la señorita Kobayashi!",
  ui_story_5060_50600401_59_dialog_content = "Sinceramente, tienes bastante descaro al decir todo eso...",
  ui_story_5060_50600401_60_dialog_content = "¿No es obvio que ya somos amigos?",
  ui_story_5060_50600401_61_dialog_content = "Cuando activé la Puerta de Teletransportación Mundial, originalmente tenía la intención de regresar a mi mundo natal y tomar algunas fotos de él...",
  ui_story_5060_50600401_62_dialog_content = "Pero ¿sabes qué? ¡Creo que el paisaje en este mundo también es bonito!",
  ui_story_5060_50600401_63_dialog_content = "Cuando todo esto termine, usemos esta cámara para tomar una foto de grupo, ¿de acuerdo?",
  ui_story_5060_50600401_64_dialog_content = "...¡Sí! Me gustaría eso!",
  ui_story_5060_50600401_65_dialog_content = "Pareces feliz, PlayerName.",
  ui_story_5060_50600401_66_dialog_content = "Recuerda sonreír así para la foto.",
  ui_story_5060_50600401_67_dialog_content = "¡Jajaja! ¡Seguro que lo haré!",
  ui_story_5060_50600401_68_dialog_content = "<color=#e8d9bb>Algún tiempo después...</color>",
  ui_story_5060_50600401_69_dialog_content = "Nos estamos acercando a la dirección de entrega.",
  ui_story_5060_50600401_70_dialog_content = "¿Cuál es exactamente el propósito de construir un Puesto Avanzado de Illumina, PlayerName? ¿Es algún tipo de estructura defensiva?",
  ui_story_5060_50600401_71_dialog_content = "Supongo que podrías decir eso.",
  ui_story_5060_50600401_72_dialog_content = "Suspiro, la Federación Illumina realmente necesita renovar sus políticas de comida si sus soldados tienen que pedir comida a domicilio para alimentarse.",
  ui_story_5060_50600401_73_dialog_content = "Por curiosidad, Tohru, ¿qué ordenó el cliente para comer?",
  ui_story_5060_50600401_74_dialog_content = "Postres, con un acompañamiento de aún más postre. Bastante raro para un cliente, ¿verdad?",
  ui_story_5060_50600401_75_dialog_content = "Probablemente sea porque aquí les falta mucho azúcar. Puedo entenderlo totalmente.",
  ui_story_5060_50600401_76_dialog_content = "Después de todo, la guerra contra los Eclipsites es extremadamente peligrosa. Sin suficiente energía, todos estarían en serios problemas.",
  ui_story_5060_50600401_77_dialog_content = "¿Eclipsites, eh? Honestamente, no creo que sean tan fuertes... ¿Realmente son una amenaza tan grande para todo el mundo?",
  ui_story_5060_50600401_78_dialog_content = "En comparación con esos Eclipsites de hace un momento, tú y tus amigos son increíblemente poderosos.",
  ui_story_5060_50600401_79_dialog_content = "Pero en la naturaleza, estos monstruos no atacan en manadas, sino en enormes oleadas.",
  ui_story_5060_50600401_80_dialog_content = "Nuestra batalla contra los Eclipsites es una que nunca ha terminado.",
  ui_story_5060_50600401_81_dialog_content = "De cierta manera, la historia de Astra es una historia de nuestras luchas contra los Eclipsites.",
  ui_story_5060_50600401_82_dialog_content = "Realmente no puedes permitirte bajar la guardia en este mundo, ¿verdad?",
  ui_story_5060_50600401_83_dialog_content = "¡Mira, humo!",
  ui_story_5060_50600401_84_dialog_content = "Tohru, PlayerName, ¡miren allá abajo! ¡Los Eclipsites están atacando una aldea!",
  ui_story_5060_50600401_85_dialog_content = "¡Lo veo! Solo dame un minuto y encontraré un lugar para aterrizar.",
  ui_story_5060_50600401_86_dialog_content = "Si atacan demasiados Eclipsites, el puesto avanzado de Illumina podría no ser capaz de resistirlos.",
  ui_story_5060_50600401_87_dialog_content = "Mucha gente está herida.",
  ui_story_5060_50600401_88_dialog_content = "Quiero ayudarles...",
  ui_story_5060_50600401_89_dialog_content = "Estas personas viven vidas tan difíciles. Todos ellos se ven tan cansados y asustados.",
  ui_story_5060_50600401_90_dialog_content = "Sí, y puedes notar que algunos de ellos vienen de áreas aún más lejanas y menos defendidas de la Federación Illumina.",
  ui_story_5060_50600401_91_dialog_content = "Em...",
  ui_story_5060_50600401_92_dialog_content = "¿Eh? ¡No!",
  ui_story_5060_50600401_93_dialog_content = "......",
  ui_story_5060_50600401_94_dialog_content = "Quería ayudarla, pero se escapó.",
  ui_story_5060_50600401_95_dialog_content = "Mi suposición es que, después de experimentar tanta destrucción hace poco, estas personas no tienen la fuerza para lidiar con extraños.",
  ui_story_5060_50600401_96_dialog_content = "Deberíamos dejarles algo de comida aquí y darles suficiente espacio para que se calmen.",
  ui_story_5060_50600401_97_dialog_content = "Este realmente no parece ser el momento para entregar pedidos para llevar...",
  ui_story_5060_50600401_98_dialog_content = "¡Hey! Escuchen, ¡Eclipsitas podridos!",
  ui_story_5060_50600401_99_dialog_content = "Si me reportan por llegar tarde, ¡puedes despedirte de tu mundo natal! Si entiendes lo que digo, entonces—",
  ui_story_5060_50600401_100_dialog_content = "... ¿Estos tipos realmente son incapaces de comunicarse?",
  ui_story_5060_50600401_101_dialog_content = "Supongo que no tengo opción... más que romper un poco las reglas de este mundo.",
  ui_story_5060_50600501_1_dialog_content = "Tantos eclipses...",
  ui_story_5060_50600501_2_dialog_content = "¡Qué dolor! ¡Realmente atacan en oleadas!",
  ui_story_5060_50600501_3_dialog_content = "Si no hubiera gente de la Federación Illumina entre ellos, podría freírlos a todos con mi Aliento de Dragón...",
  ui_story_5060_50600501_4_dialog_content = "¡Hagan su mejor esfuerzo, todos! ¡Yo también trabajaré duro para brindar apoyo moral!",
  ui_story_5060_50600501_5_dialog_content = "¡Ven aquí y ayúdanos!",
  ui_story_5060_50600501_6_dialog_content = "Deben haber construido un nido en algún lugar cercano. No avanzaremos a menos que lo encontremos rápidamente y lo destruyamos.",
  ui_story_5060_50600501_7_dialog_content = "¡Déjame eso a mí! Una vez que me transforme en mi forma de dragón...",
  ui_story_5060_50600501_8_dialog_content = "<size=45>¡Todos!</size>",
  ui_story_5060_50600501_9_dialog_content = "¡Los soldados Illumina y yo acabamos de destruir el nido que está más adelante!",
  ui_story_5060_50600501_10_dialog_content = "¡Mantengan la línea y acaben con el resto de las fuerzas enemigas!",
  ui_story_5060_50600501_11_dialog_content = "¡Que cada resto malvado sea aplastado por el poder del orden!",
  ui_story_5060_50600501_12_dialog_content = "¡Es el subcapitán <color=#FFB400>Elma</color>!",
  ui_story_5060_50600501_13_dialog_content = "¡El capitán Elma se ve tan elegante!",
  ui_story_5060_50600501_14_dialog_content = "(¡Maldita sea, me muero de hambre! ¿Por qué mi comida aún no ha sido entregada?!)",
  ui_story_5060_50600501_15_dialog_content = "(Si esta comida sabe mal, ¡definitivamente les dejaré una reseña de una estrella!)",
  ui_story_5060_50600502_1_dialog_content = "Uf... Todos se han ido ahora. Hora de recargar energías.",
  ui_story_5060_50600502_2_dialog_content = "Em...",
  ui_story_5060_50600502_3_dialog_content = "Oye, es la chica que huyó de mí hace un momento.",
  ui_story_5060_50600502_4_dialog_content = "Lo siento por antes... Estaba tan asustado...",
  ui_story_5060_50600502_5_dialog_content = "Por eso me escapé... Definitivamente, definitivamente no es porque no me gustes.",
  ui_story_5060_50600502_6_dialog_content = "La batalla de hace un momento... ¡fue realmente increíble!",
  ui_story_5060_50600502_7_dialog_content = "Pareces de mi edad, pero... ¡eres realmente elegante, astuto y genial!",
  ui_story_5060_50600502_8_dialog_content = "¡Me gustaría regalarte esta flor!",
  ui_story_5060_50600502_9_dialog_content = "Oh, ella se escapó de nuevo.",
  ui_story_5060_50600502_10_dialog_content = "Sí, pero parece que esta vez escapó por timidez en lugar de miedo.",
  ui_story_5060_50600502_11_dialog_content = "Creo que acabas de hacer un nuevo amigo en este mundo, Kanna!",
  ui_story_5060_50600502_12_dialog_content = "¿Un amigo...?",
  ui_story_5060_50600502_13_dialog_content = "¿Siempre me estará observando?",
  ui_story_5060_50600502_14_dialog_content = "¡Jajaja, estoy seguro de que lo hará! Mira, aunque se esté escondiendo detrás de esa roca allá, ¡todavía te está mirando!",
  ui_story_5060_50600502_15_dialog_content = "Ya terminé de recargar.",
  ui_story_5060_50600502_16_dialog_content = "¡Bien! Ahora que los Eclipsites están resueltos, es hora de entregar este pedido a su legítimo dueño.",
  ui_story_5060_50600502_17_dialog_content = "Sabes, encontrarme con ella como repartidora en este mundo realmente es un giro del destino.",
  ui_story_5060_50600502_18_dialog_content = "La forma en que dijiste eso... ¿Conoces a la persona que hizo el pedido, Tohru? Pensé que era alguien de la Federación Illumina.",
  ui_story_5060_50600502_19_dialog_content = "No, definitivamente es una de las nuestras. Nadie más haría un pedido así.",
  ui_story_5060_50600502_20_dialog_content = "¿No es así, Elma?",
  ui_story_5060_50600502_21_dialog_content = "¡Mis postres! ¡Finalmente aparecieron!",
  ui_story_5060_50600502_22_dialog_content = "¿Eh? ¿Tohru?! ¡¿Qué estás haciendo aquí?!",
  ui_story_5060_50600502_23_dialog_content = "¿Pensabas comerte todos esos antes de hablar conmigo...?",
  ui_story_5060_50600502_24_dialog_content = "¡Vine a entregar tu comida!",
  ui_story_5060_50600502_25_dialog_content = "Tuve que conseguir un trabajo en este mundo solo para ganar dinero y buscar pistas sobre tu paradero, ya sabes...",
  ui_story_5060_50600502_26_dialog_content = "...Y a juzgar por el tamaño de este pedido, probablemente pediste uno de cada cosa del menú de postres del Sr. Liu, ¿verdad?!",
  ui_story_5060_50600502_27_dialog_content = "¡No pude evitarlo! ¡Casi me muero de hambre cuando llegamos a este mundo!",
  ui_story_5060_50600502_28_dialog_content = "No fue fácil, pero logré usar mi clarividencia para encontrar un pajarito con un volante atado a su pata...",
  ui_story_5060_50600502_29_dialog_content = "¡Y todo en el menú se veía tan delicioso!",
  ui_story_5060_50600502_30_dialog_content = "Así que revisé todas las casillas del menú de postres y ¡hice una salsa para mojar con líquidos de Eclipsite!",
  ui_story_5060_50600502_31_dialog_content = "Después de eso, até el menú de nuevo en la pata del pajarito y lo dejé volar.",
  ui_story_5060_50600502_32_dialog_content = "Pero luego empecé a tener mucha hambre de nuevo mientras más Eclipsites nos atacaban. Estaba preocupado de no haber hecho mi pedido correctamente, ya que mi comida nunca llegó.",
  ui_story_5060_50600502_33_dialog_content = "¡Pero al final, apareció justo a tiempo! ¡Jejejeje!",
  ui_story_5060_50600502_34_dialog_content = "Ya veo. En ese caso—",
  ui_story_5060_50600502_35_dialog_content = "¡Gracias por hacer negocios! Si disfrutas de la comida, ¡recuerda darnos una calificación de cinco estrellas!",
  ui_story_5060_50600502_36_dialog_content = "¡Aquí está la factura de la comida más el envío!",
  ui_story_5060_50600502_37_dialog_content = "¿Eh? ¿Qué dijiste?",
  ui_story_5060_50600502_38_dialog_content = "<size=45>¡Aquí está la factura de la comida más el envío!</size>",
  ui_story_5060_50600502_39_dialog_content = "...¿P-Por casualidad, aceptan yenes japoneses...?",
  ui_story_5060_50600502_40_dialog_content = "¡No seas tonto, estimado cliente! Nuestra tienda solo acepta Nightium, como seguramente sabes.",
  ui_story_5060_50600502_41_dialog_content = "Entonces entrega—todo tu—Nightium—",
  ui_story_5060_50600502_42_dialog_content = "...Estás siendo demasiado aterrador, Tohru!",
  ui_story_5060_50600502_43_dialog_content = "Cubriré la cuenta del Subcapitán. Después de todo, ella salvó nuestras vidas.",
  ui_story_5060_50600502_44_dialog_content = "¡Inclúyeme! ¡La fuerza del Subcapitán vale más que unos cuantos Nightiums!",
  ui_story_5060_50600502_45_dialog_content = "*Sniffle* Yo... Estoy tan conmovido, ¡a todos!",
  ui_story_5060_50600502_46_dialog_content = "Descansemos y reagrupémonos por ahora, ¡así podremos atacar el campamento principal de los Eclipsites! ¡Exterminaremos a cada uno de ellos!",
  ui_story_5060_50600502_47_dialog_content = "¡Esplendor Illumina!!",
  ui_story_5060_50600502_48_dialog_content = "......",
  ui_story_5060_50600502_49_dialog_content = "PlayerName está demasiado atónito para hablar.",
  ui_story_5060_50600502_50_dialog_content = "E gener of Silenced Balkis of recomparison  one example of a sentence,",
  ui_story_5060_50600502_51_dialog_content = "Como un dragón respetuoso de la ley de la Facción de la Armonía, me sorprende que también estés cumpliendo con tus responsabilidades en este mundo.",
  ui_story_5060_50600502_52_dialog_content = "T-Tengo una buena razón para eso... ¡Y tú eres uno para hablar, Tohru!",
  ui_story_5060_50600502_53_dialog_content = "Solo mírate... Una sirvienta dragón entregando comida oriental en una moto...",
  ui_story_5060_50600502_54_dialog_content = "¡No pareces actuar como un dragón de la Facción del Caos en absoluto!",
  ui_story_5060_50600502_55_dialog_content = "Como dije, ¡solo estoy haciendo esto para encontrarlos a todos y así podamos regresar a casa más pronto!",
  ui_story_5060_50600502_56_dialog_content = "Tohru y Elma son como el fuego y el agua, como siempre.",
  ui_story_5060_50600502_57_dialog_content = "Jejeje, aún no entiendes los sentimientos entre viejos enemigos, Kanna.",
  ui_story_5060_50600502_58_dialog_content = "Puede que - 2d0,",
  ui_story_5060_50600502_59_dialog_content = "Ahora que la batalla ha terminado y todos de la Federación Illumina están regresando...",
  ui_story_5060_50600502_60_dialog_content = "¿Por qué no nos sentamos y comemos primero? Luego podemos hablar de buscar más información por aquí.",
  ui_story_5060_50600502_61_dialog_content = "Todos tienen hambre, y el único que comió fue Elma...",
  ui_story_5060_50600502_62_dialog_content = "...Pero estoy seguro de que puede comer otra comida.",
  ui_story_5060_50600502_63_dialog_content = "¡De acuerdo, cuéntenme! Celebremos nuestra victoria con una gran fiesta de comida.",
  ui_story_5060_50600502_64_dialog_content = "¡Eso huele tan bien!",
  ui_story_5060_50600502_65_dialog_content = "¡Esta comida es increíble! ¡Puedo sentir cómo mi poder regresa a mí!",
  ui_story_5060_50600502_66_dialog_content = "Jajaja, ¡me alegra que te guste! Un amigo me enseñó a hacer esto hace un tiempo.",
  ui_story_5060_50600502_67_dialog_content = "Como era de esperarse, ¡nosotros los Aurorianos y Caelestites somos los compañeros perfectos!",
  ui_story_5060_50600502_68_dialog_content = "Pero tú eres un dragón.",
  ui_story_5060_50600502_69_dialog_content = "daytime_translation<|im_sep|>Todo (really early on and and ol.lery Rheims hid registered for this content hes and uncategorized/doctrine/12. H in bid or possibly coulding,, and and, in,4u in1 yet another example of to show 's for toer.,*",
  ui_story_5060_50600502_70_dialog_content = "Suspiro, ¿qué vamos a hacer contigo...",
  ui_story_5060_50600502_71_dialog_content = "También traje algunos bollos al vapor del Sr. Liu. ¡Prueben uno, todos!",
  ui_story_5060_50600502_72_dialog_content = "¡Guarda algo para mí, Tohru!",
  ui_story_5060_50600502_73_dialog_content = "Kanna dijo algo sobre ustedes dos siendo como agua y fuego, ¿no es cierto?",
  ui_story_5060_50600502_74_dialog_content = "La gente no suele describir a los amigos de esa manera. ¿Cuál es la historia entre ustedes dos?",
  ui_story_5060_50600502_75_dialog_content = "Supongo que se puede decir que ahora somos amigos, pero solíamos ser enemigos mortales.",
  ui_story_5060_50600502_76_dialog_content = "Soy un dragón de la Facción del Caos, mientras que ella pertenece a la Facción de la Armonía.",
  ui_story_5060_50600502_77_dialog_content = "Es un poco difícil imaginar que ustedes dos eran enemigos solo por sus facciones.",
  ui_story_5060_50600502_78_dialog_content = "Después de todo, el conflicto está destinado a existir en cualquier mundo.",
  ui_story_5060_50600502_79_dialog_content = "En el mundo de donde venimos...",
  ui_story_5060_50600502_80_dialog_content = "Quizás no tengamos que lidiar con criaturas repugnantes como los Eclipsites todos los días, como en tu mundo...",
  ui_story_5060_50600502_81_dialog_content = "Siempre habrá criaturas con puntos de vista diferentes. Naturalmente, lo mismo ocurre con los dragones que se niegan a llevarse bien.",
  ui_story_5060_50600502_82_dialog_content = "Pero aún quiero creer lo que Kobayashi me dijo—",
  ui_story_5060_50600502_83_dialog_content = "Si todos están dispuestos a comunicarse y tratarse como aliados, entonces no habría más conflictos en el mundo.",
  ui_story_5060_50600502_84_dialog_content = "¡Justo como cuando mezclamos tu cocina con los bollos al vapor del Sr. Liu, hace que todo sepa el doble de delicioso!",
  ui_story_5060_50600502_85_dialog_content = "Creo que Elma se va a comer todo ella misma.",
  ui_story_5060_50600502_86_dialog_content = "Jajaja, estoy de acuerdo. Las metáforas del Subcapitán son bastante peculiares, en efecto.",
  ui_story_5060_50600502_87_dialog_content = "Recuerdo cuando conocí a la Subcapitana; solía ser un poco reservada, hablando siempre de etiqueta y reglas.",
  ui_story_5060_50600502_88_dialog_content = "Ahora, ¡se ha convertido en una excelente soldado de avanzada! Ser un poco rara no es gran cosa.",
  ui_story_5060_50600502_89_dialog_content = "Es extraño, pero desde que nos reencontramos, Elma no me ha dicho nada sobre alterar el orden del mundo...",
  ui_story_5060_50600502_90_dialog_content = "O volver a donde pertenezco.",
  ui_story_5060_50600502_91_dialog_content = "Tampoco ha arrasado montañas ni destruido casas de personas en nombre de mantener el orden.",
  ui_story_5060_50600502_92_dialog_content = "Deja de intentar provocar problemas, Tohru...",
  ui_story_5060_50600502_93_dialog_content = "Muy bien, Subcapitán, tengo algunos dulces aquí.",
  ui_story_5060_50600502_94_dialog_content = "Sé que eres goloso, así que todo esto es para ti.",
  ui_story_5060_50600502_95_dialog_content = "¡Oh, ustedes son los mejores! Estoy tan contento de haber encontrado un trabajo como este en su mundo...",
  ui_story_5060_50600502_96_dialog_content = "¡Ustedes siempre serán mis amigos!",
  ui_story_5060_50600502_97_dialog_content = "Estás haciendo amigos un poco demasiado casualmente, ¿no crees?",
  ui_story_5060_50600502_98_dialog_content = "Honestamente, ¿cómo logras adaptarte a cualquier ambiente en el que te encuentras?",
  ui_story_5060_50600502_99_dialog_content = "¿Todos en la Facción de la Armonía tienen este regalo?",
  ui_story_5060_50600601_1_dialog_content = "Nos hemos encontrado con esos criminales que mencionó PlayerName! Vinieron aquí desde el desierto de Rediesel.",
  ui_story_5060_50600601_2_dialog_content = "En ese momento, descubrimos que esta gente intentaba escabullirse en nuestro puesto de avanzada utilizando métodos prohibidos.",
  ui_story_5060_50600601_3_dialog_content = "Mientras negociábamos e intentábamos arrestarlos, nos emboscaron los Eclipsites y no pudimos capturarlos.",
  ui_story_5060_50600601_4_dialog_content = "Todo gracias a la intervención del Subcapitán Elma, nos salvamos; de lo contrario, seguro que habríamos sido enterrados bajo las arenas amarillas.",
  ui_story_5060_50600601_5_dialog_content = "¡No lo menciones! Ustedes también me salvaron de morir de hambre en la naturaleza, ¿recuerdan?",
  ui_story_5060_50600601_6_dialog_content = "Bueno, parece que encontraremos un bastión o ruta de transporte para los contrabandistas en algún lugar del Desierto de Rediesel.",
  ui_story_5060_50600601_7_dialog_content = "¡Después de todo, venir a este puesto avanzado de Illumina fue la decisión correcta!",
  ui_story_5060_50600601_8_dialog_content = "Pero aún no hemos escuchado nada acerca de Fafnir.",
  ui_story_5060_50600601_9_dialog_content = "Es cierto. Hice que algunas personas se conectaran a la red de inteligencia de Illumina para obtener más información, pero no encontramos nada.",
  ui_story_5060_50600601_10_dialog_content = "Pero no hay necesidad de preocuparse. Fafnir es el tipo de persona que sobrevive sin importar dónde se encuentre.",
  ui_story_5060_50600601_11_dialog_content = "¿Y quién sabe? Tal vez nos encontremos con tu último amigo perdido en nuestra próxima dirección de entrega.",
  ui_story_5060_50600601_12_dialog_content = "Este mundo puede ser bastante pequeño, después de todo.",
  ui_story_5060_50600601_13_dialog_content = "Estás en lo correcto.",
  ui_story_5060_50600601_14_dialog_content = "¿Qué comida estamos entregando esta vez, Tohru?",
  ui_story_5060_50600601_15_dialog_content = "Esta en realidad no es una orden de comida. La tienda le gusta agradecer a sus clientes habituales con algunas salsas especiales, así que eso es lo que estamos entregando.",
  ui_story_5060_50600601_16_dialog_content = "Y la dirección está en... ¿El Desierto de Rediesel? Vaya, qué coincidencia. ¿Aparecerá Fafnir también por ahí?",
  ui_story_5060_50600601_17_dialog_content = "¿Recuerdas lo que dijeron esos contrabandistas? Se arriesgaron a ser perseguidos por un dragón solo para robarle algún tipo de tesoro.",
  ui_story_5060_50600601_18_dialog_content = "¿El dragón de la colección de la subasta?",
  ui_story_5060_50600601_19_dialog_content = "Cuando escuché a los contrabandistas, supe que definitivamente no estaban hablando de Fafnir.",
  ui_story_5060_50600601_20_dialog_content = "No importa en qué mundo esté o quién sea su oponente, Fafnir recurrirá a cualquier medio para adquirir tesoros.",
  ui_story_5060_50600601_21_dialog_content = "¿Tu amigo realmente es tan aterrador?",
  ui_story_5060_50600601_22_dialog_content = "No te preocupes, ¡él es conocido por llevarse pacíficamente con otras personas! ¡Solo que no con tantas de ellas!",
  ui_story_5060_50600601_23_option_content = "Todavía suena un poco aterrador...",
  ui_story_5060_50600601_24_option_content = "Suena como un dragón inaccesible",
  ui_story_5060_50600601_25_dialog_content = "Relájate, estás con nosotros, ¿recuerdas? Si lo peor llega a pasar, ¡simplemente nos uniremos contra él!",
  ui_story_5060_50600601_26_dialog_content = "Aunque todavía tengo bastante miedo, tenemos que seguir adelante...",
  ui_story_5060_50600601_27_dialog_content = "¡Es hora de poner fin a este incidente de contrabando en la subasta!",
  ui_story_5060_50600601_28_dialog_content = "Le prometí lo mismo a mi jefe. Si hay algo en lo que pueda ayudar, ¡haré lo posible para echar una mano!",
  ui_story_5060_50600601_29_dialog_content = "Lucoa puede ser realmente confiable cuando no está holgazaneando.",
  ui_story_5060_50600601_30_dialog_content = "¿Sabes exactamente dónde encontrar esta dirección, PlayerName?",
  ui_story_5060_50600601_31_dialog_content = "Estoy algo familiarizado con eso. Es uno de los bastiones de Rediesel Wrench.",
  ui_story_5060_50600601_32_dialog_content = "Ahora que lo pienso, probablemente ya es hora de hacer un viaje allí.",
  ui_story_5060_50600601_33_dialog_content = "Aunque recolectan en el desierto, también saben cómo participar en un comercio honesto.",
  ui_story_5060_50600601_34_dialog_content = "Pero si queremos entrar en su territorio de manera segura, es mejor que me dejes saludarlos primero.",
  ui_story_5060_50600601_35_dialog_content = "PlayerName es súper confiable.",
  ui_story_5060_50600601_36_dialog_content = "Tohru, deja tu motocicleta con estos soldados, para que puedan llevarla de vuelta al puesto de avanzada. De lo contrario, es muy probable que esos chicos de Rediesel Wrench intenten llevársela.",
  ui_story_5060_50600601_37_dialog_content = "Aunque normalmente conducen sus propios vehículos, es mejor estar preparados.",
  ui_story_5060_50600601_38_dialog_content = "No te preocupes, señorita Tohru. ¡Nos encargaremos de esta moto!",
  ui_story_5060_50600601_39_dialog_content = "¿Adónde se arrastraron esos contrabandistas sinvergüenzas?!",
  ui_story_5060_50600601_40_dialog_content = "Parece que los contrabandistas ya cruzaron la Rediesel Wrench. No deben tener miedo de nadie...",
  ui_story_5060_50600601_41_dialog_content = "¡Permítanme presentarles a todos! Este es Sinsa, el líder actual de Rediesel Wrench.",
  ui_story_5060_50600601_42_dialog_content = "¡Y aquí están mis amigos más nuevos!",
  ui_story_5060_50600601_43_dialog_content = "¡Este tipo se ve realmente duro! ¿Quieres ver quién es más duro, grandote?",
  ui_story_5060_50600601_44_dialog_content = "Lo siento, pero nunca he golpeado a una mujer en mi vida, mucho menos a una sirvienta.",
  ui_story_5060_50600601_45_dialog_content = "¡Oye, PlayerName! Dijiste que sabías algo sobre esos malditos contrabandistas, ¿verdad? ¡No descansaré hasta que les dé una paliza a esos idiotas primero!",
  ui_story_5060_50600601_46_dialog_content = "¿No me digas que esos tipos te robaron algo?",
  ui_story_5060_50600601_47_dialog_content = "¡De ninguna manera! Esos tipos podrían haber sido diez veces más valientes, ¡y aún así no tendrían el valor de robarnos!",
  ui_story_5060_50600601_48_dialog_content = "La verdad es que estos contrabandistas solían ser bastante discretos aquí en el Desierto de Rediesel.",
  ui_story_5060_50600601_49_dialog_content = "No sé qué les pasó por la cabeza, pero últimamente han estado causando todo tipo de problemas.",
  ui_story_5060_50600601_50_dialog_content = "Casi parecían delirantes, corriendo y gritando sobre monstruos y \"condenas inminentes\" o algo así.",
  ui_story_5060_50600601_51_dialog_content = "¡Ya han impactado enormemente nuestras operaciones diarias!",
  ui_story_5060_50600601_52_dialog_content = "¡Por culpa de ellos, apenas tenemos caravanas de Lumopolis atravesando el desierto!",
  ui_story_5060_50600601_53_dialog_content = "Oh... Eh...",
  ui_story_5060_50600601_54_dialog_content = "¿Realmente tienes información sobre ellos? Si la tienes, ¡dilo ya!",
  ui_story_5060_50600601_55_dialog_content = "N-Nos íbamos a preguntar si nos podías dar más información sobre ellos.",
  ui_story_5060_50600601_56_dialog_content = "¿Como si hubieran perdido algún tesoro recientemente?",
  ui_story_5060_50600601_57_dialog_content = "Únete a Rediesel Wrench y quizás me incline a decírtelo.",
  ui_story_5060_50600601_58_dialog_content = "No esto otra vez... No importa, simplemente iré a preguntarle a Odi.",
  ui_story_5060_50600601_59_dialog_content = "Ella es la que está pendiente de todo por aquí.",
  ui_story_5060_50600601_60_dialog_content = "Pareces realmente popular, PlayerName.",
  ui_story_5060_50600601_61_dialog_content = "¡Oh, cierto! Casi lo olvido.",
  ui_story_5060_50600601_62_dialog_content = "¡Permíteme presentarme! Mi nombre es Tohru, ¡una sirvienta de reparto del restaurante del Sr. Liu!",
  ui_story_5060_50600601_63_dialog_content = "¿Alguien aquí es un cliente habitual del Sr. Liu? Si es así, ¡tengo salsa para entregar en su nombre!",
  ui_story_5060_50600601_64_dialog_content = "¡Vaya, nunca pensé que tendría en mis manos algo tan bueno! ¡Entrégamelo rápido!",
  ui_story_5060_50600601_65_dialog_content = "He sido yo quien ha salido a buscarlo varias veces; ¿¡por qué debería dejarte tenerlo?!",
  ui_story_5060_50600601_66_dialog_content = "¡Son mis cupones los que todos ustedes han estado usando!",
  ui_story_5060_50600601_67_dialog_content = "¡Dejen de pelear o confiscaré todo!",
  ui_story_5060_50600601_68_dialog_content = "Vamos a regresar primero al bastión de Rediesel Wrench. Vamos, PlayerName; tú y tus amigos pueden viajar conmigo.",
  ui_story_5060_50600601_69_dialog_content = "El resto de ustedes pueden seguirme en el otro coche detrás de mí.",
  ui_story_5060_50600601_70_dialog_content = "Cosa segura.",
  ui_story_5060_50600601_71_dialog_content = "¡Muy bien, amigos! ¡Es hora de experimentar la velocidad y emoción de la Rediesel Wrench!",
  ui_story_5060_50600601_72_dialog_content = "¡Ahora agárrate fuerte!",
  ui_story_5060_50600601_73_dialog_content = "<size=45>¡Despegue!</size>",
  ui_story_5060_50600601_74_dialog_content = "¡GUAUOO! ¡Qué forma tan increíble de conducir!",
  ui_story_5060_50600601_75_dialog_content = "¿Estás bien Micah 1./DV, <?, in in the past,, Kanna?",
  ui_story_5060_50600601_76_dialog_content = "Estoy bien. ¡Qué emocionante!",
  ui_story_5060_50600601_77_dialog_content = "Eso es bueno, pero parece que algo anda mal con PlayerName!",
  ui_story_5060_50600601_78_dialog_content = "No te sientes mareado en el coche, ¿verdad?",
  ui_story_5060_50600601_79_dialog_content = "¡Un piloto de Colossus nunca podría marearse en un coche!",
  ui_story_5060_50600601_80_dialog_content = "Sabes, no es bueno esforzarse demasiado, ¿verdad?",
  ui_story_5060_50600601_81_dialog_content = "¡Apóyate en mí y todo estará bien!",
  ui_story_5060_50600601_82_dialog_content = "N... No, gracias.",
  ui_story_5060_50600601_83_dialog_content = "¿Sentiste la velocidad y emoción de la Rediesel Wrench?",
  ui_story_5060_50600601_84_dialog_content = "on 17 par…t, 1. and the choicesthe choice is yours, and in the woods, and one﻿... The trails:Thisations-quota,ound , FB, they are, to get a email, the same, but not only, but of the,, on the, they are?  cold   Empower  that's the.  with thee,. ( , in the at. incerely. lightly NE MD  and in. . the - or. .. with this and no other, to not  to     a,-h. as the . ram and to Well  th/a in unsatches cures, the  Wallace of to the  to 50oba, on the other of the not and  valuable and\n\n .   in collectively.  in order-ch or: if Od paper forar in   who",
  ui_story_5060_50600601_85_dialog_content = "Antes de conocerte, no podía dejar de preguntarme cómo era el Rediesel Wrench.",
  ui_story_5060_50600601_86_dialog_content = "Después de todo, PlayerName dijo que eras el tipo de persona que tomaría mi motocicleta a la fuerza.",
  ui_story_5060_50600601_87_dialog_content = "Pensé que ustedes serían un grupo de matones con malas actitudes...",
  ui_story_5060_50600601_88_dialog_content = "Pero ahora veo que me equivoqué al pensar eso.",
  ui_story_5060_50600601_89_dialog_content = "¡Jajaja, no te preocupes por eso! Todos cometemos errores de vez en cuando.",
  ui_story_5060_50600601_90_dialog_content = "Pero mientras hablemos abiertamente y confiemos el uno en el otro, ¡siempre seremos amigos corriendo por este loco desierto!",
  ui_story_5060_50600601_91_dialog_content = "¡Rediesel Wrench se trata de libertad!",
  ui_story_5060_50600601_92_dialog_content = "Un poco demasiada libertad, si me preguntas—",
  ui_story_5060_50600801_1_dialog_content = "Me siento mareado.",
  ui_story_5060_50600801_2_dialog_content = "Realmente mareado.",
  ui_story_5060_50600801_3_dialog_content = "Ven aquí, Kanna. Déjame abrazarte.",
  ui_story_5060_50600801_4_dialog_content = "No pensé que serías tú quien terminaría mareado en el auto.",
  ui_story_5060_50600801_5_dialog_content = "No hay remedio; después de todo, ella sigue siendo muy joven y estoy seguro de que es su primera vez en un viaje tan accidentado.",
  ui_story_5060_50600801_6_dialog_content = "De todos modos, me está empezando a dar hambre. ¿Cuándo podemos comer?",
  ui_story_5060_50600801_7_dialog_content = "Estuviste to est,ar de que te qued...",
  ui_story_5060_50600801_8_dialog_content = "¡N-No! ¡He estado alerta de los Eclipsites todo el tiempo!",
  ui_story_5060_50600801_9_dialog_content = "Derribamos un montón de ellos antes. Podrías haber comido tantos como quisieras.",
  ui_story_5060_50600801_10_dialog_content = "Spanish_translation<|im_sep|>¿¡Cómo podría collins, you, our, may, to, going,,, and, the, and, and, and,, Legion is the, and, and KIT,...",
  ui_story_5060_50600801_11_dialog_content = "Bueno, ¿qué pasa con los dulces que te dieron esos soldados Iluminados?",
  ui_story_5060_50600801_12_dialog_content = "¡Esos son una muestra de nuestra camaradería!",
  ui_story_5060_50600801_13_dialog_content = "Text: in  to Wend.sleaving  in ed. - - the first time I've ever seen been able to use the word-0. Freddy the Bear (Fred) has not been able to and for deliberately from the 2.",
  ui_story_5060_50600801_14_dialog_content = "Ah, olvídalo... Toma. El Sr. Liu me dio unos cuantos extra, pero no puedo comerlos todos.",
  ui_story_5060_50600801_15_dialog_content = "Realmente eres un buen amigo, Tohru!",
  ui_story_5060_50600801_16_dialog_content = "¡A-Apartate de mí!",
  ui_story_5060_50600801_17_dialog_content = "Después de haber sobrevivido a una batalla tan intensa hace poco, ustedes dos están llenos de energía.",
  ui_story_5060_50600801_18_dialog_content = "¿Hablas de esos Eclipsites en el desierto? ¡Lidiar con esas plagas no es nada para alguien como yo!",
  ui_story_5060_50600801_19_dialog_content = "Aun así, cuando finalmente llegamos al desierto, pensé que habría muchos menos de ellos aquí.",
  ui_story_5060_50600801_20_dialog_content = "Entonces, ¿por qué todavía hay tantos Eclipsites?",
  ui_story_5060_50600801_21_dialog_content = "Si hay algo que no falta en este mundo, son los Eclipsites. Dondequiera que encuentres Aurorianos, esos monstruos nunca estarán demasiado lejos—",
  ui_story_5060_50600801_22_dialog_content = "¡Pero incluso los lugares sin Aurorianos están llenos de Eclipsites!",
  ui_story_5060_50600801_23_dialog_content = "Bueno, gracias al amplio sistema de vigilancia de Odi, podemos rastrear la mayoría de sus movimientos y prepararnos adecuadamente.",
  ui_story_5060_50600801_24_dialog_content = "También te ayuda a defender tus fortalezas del ejército de Lumopolis, ¿verdad?",
  ui_story_5060_50600801_25_dialog_content = "¡Jajaja! ¡Directo como siempre, PlayerName! ¡Eso es lo que me gusta de ti!",
  ui_story_5060_50600801_26_dialog_content = "Está bien, Odi debería estar adentro. Pregúntale lo que quieras.",
  ui_story_5060_50600801_27_dialog_content = "Odi—",
  ui_story_5060_50600801_28_dialog_content = "¿Eh? ¿Quién es el que está junto a ella?",
  ui_story_5060_50600801_29_dialog_content = "Eres bastante bueno, <color=#FFB400>Fafnir</color>, pero si quieres vencerme...",
  ui_story_5060_50600801_30_dialog_content = "¡Todavía tienes un largo camino por recorrer!",
  ui_story_5060_50600801_31_dialog_content = "Toma esto—",
  ui_story_5060_50600801_32_dialog_content = "<size=45>¡Perforador de estrellas!</size>",
  ui_story_5060_50600801_33_dialog_content = "¡Espera, no uses ese movimiento!",
  ui_story_5060_50600801_34_dialog_content = "......",
  ui_story_5060_50600801_35_dialog_content = "Fafnir se veía tan herido; ni siquiera nos saludó cuando entramos.",
  ui_story_5060_50600801_36_dialog_content = "Oye Fafnir, ¿sigues vivo?",
  ui_story_5060_50600801_37_dialog_content = "Creo que su alma ya abandonó su cuerpo. Debe haber perdido realmente mal.",
  ui_story_5060_50600801_38_dialog_content = "No perdí. Simplemente no estoy de humor, eso es todo.",
  ui_story_5060_50600801_39_dialog_content = "¡Mucho tiempo sin verte, PlayerName! ¿Traes a estos nuevos amigos para jugar juegos hoy?",
  ui_story_5060_50600801_40_dialog_content = "Sí. Y también resulta que son amigos de Fafnir.",
  ui_story_5060_50600801_41_dialog_content = "(Así que este es Fafnir... Tiene una mirada tan feroz en sus ojos.)",
  ui_story_5060_50600801_42_dialog_content = "(En un momento como este, un saludo amistoso parece extremadamente importante para cerrar la brecha entre nosotros.)",
  ui_story_5060_50600801_43_dialog_content = "¡Hola, Faffy! Mi nombre es PlayerName y soy uno de los Tohru...",
  ui_story_5060_50600801_44_dialog_content = "No me llames con un nombre tan informal.",
  ui_story_5060_50600801_45_dialog_content = "Eh... De todos modos, vinimos aquí para pedirle a Odi un poco de información.",
  ui_story_5060_50600801_46_dialog_content = "Mientras no me pidas unirme a Rediesel Wrench, aceptaremos cualquier condición que tengas para nosotros.",
  ui_story_5060_50600801_47_dialog_content = "\"¿Condiciones\"? ¡No me importa eso! Acabo de pisotear a este tipo trescientas veces seguidas, ¡así que estoy de muy buen humor!",
  ui_story_5060_50600801_48_dialog_content = [[
It Daily, In DI to and other tiring  the  of| 3.5. are in the first A 3rd 1.0 tall.  3, 2,628th time.
