<|ipynb_marker|> Output

  3. of course, then 3,  1, 4, 5, 6, , 1,  torch,  1, 2 2, 3, 4,  5,  6, 7, 8,. 3, 1,  2, 3, 4, 5, 6 1, 2, -T 1 fo , 1, 2, 3, 3, 4  1, in the .   0 a bit,   3--t-al]],
  ui_story_5060_50600801_49_dialog_content = "Eh, lo suficientemente cerca. De todos modos, te ayudaré gratis esta vez.",
  ui_story_5060_50600801_50_dialog_content = "(Gracias, <size=45>¡Faffy!</size>)",
  ui_story_5060_50600801_51_dialog_content = "Necesito tu ayuda para encontrar algunas imágenes relacionadas con un grupo de contrabandistas. Puedo mostrarte más o menos hacia dónde se dirigían...",
  ui_story_5060_50600801_52_dialog_content = "Entonces estuviste con la Rediesel Wrench todo este tiempo, Fafnir?",
  ui_story_5060_50600801_53_dialog_content = "Eres un dragón que acumula tesoros, pero a juzgar por su naturaleza... Está claro que Rediesel Wrench es un grupo de cazadores de tesoros.",
  ui_story_5060_50600801_54_dialog_content = "Honestamente, me sorprende que te hayas quedado tanto tiempo...",
  ui_story_5060_50600801_55_dialog_content = "¿Te sobornaron con un suministro de golosinas para toda la vida o algo así?!",
  ui_story_5060_50600801_56_dialog_content = "Fafnir no es un glotón insaciable como tú, Elma.",
  ui_story_5060_50600801_57_dialog_content = "Mientras mi oponente se gane mi aprobación, no tengo problema en interactuar con ellos como iguales.",
  ui_story_5060_50600801_58_dialog_content = "No tiene absolutamente nada que ver con la profesión, el estatus o el valor en la sociedad.",
  ui_story_5060_50600801_59_dialog_content = "¿A dónde vas, Fafnir?",
  ui_story_5060_50600801_60_dialog_content = "Voy a salir a tomar aire.",
  ui_story_5060_50600801_61_dialog_content = "¿Cómo pude perder tan miserablemente? ¿En qué me equivoqué?",
  ui_story_5060_50600801_62_dialog_content = "¿Podría ser una cuestión de fuerza de voluntad?",
  ui_story_5060_50600802_1_dialog_content = "¿Qué quieres? Todavía estoy pensando en una forma de derrotar a Odi.",
  ui_story_5060_50600802_2_dialog_content = "No te preocupes, tendrás todo el tiempo del mundo para pensar en ello más tarde.",
  ui_story_5060_50600802_3_dialog_content = "Solo vuelve adentro por ahora. Odi tiene algo que decirte.",
  ui_story_5060_50600802_4_dialog_content = "Hmph... Estoy seguro de que solo quiere jactarse de sus victorias.",
  ui_story_5060_50600802_5_dialog_content = "Odio admitirlo, pero en este momento... Ella es mejor que yo.",
  ui_story_5060_50600802_6_dialog_content = "Será mejor que cuides tu tono.",
  ui_story_5060_50600802_7_dialog_content = "Si te pasas de la raya, podría maldecirte hasta convertirte en polvo.",
  ui_story_5060_50600802_8_dialog_content = "¿De qué diablos está hablando?",
  ui_story_5060_50600802_9_dialog_content = "No le hagas caso, ¡solo le gusta sonar atrevido!",
  ui_story_5060_50600802_10_dialog_content = "Te fuiste tan rápido hace un momento que no tuve tiempo de darte mi regalo.",
  ui_story_5060_50600802_11_dialog_content = "¿Tu regalo? ¿Para mí?",
  ui_story_5060_50600802_12_dialog_content = "Aquí está, la última versión de esta máquina de juego.",
  ui_story_5060_50600802_13_dialog_content = "¡Anímate, Fafnir! Mis manos geniales construyeron esto desde cero, ¡lo que lo hace tan valioso como cualquier tesoro!",
  ui_story_5060_50600802_14_dialog_content = "Entonces, ¿no me vas a humillar?",
  ui_story_5060_50600802_15_dialog_content = "¿Humillarte? Ya no hay necesidad de eso. Además, te reconocí como un oponente digno hace mucho tiempo.",
  ui_story_5060_50600802_16_dialog_content = "Incluso un adicto a los juegos como Gronru no pudo darme los datos de prueba que necesitaba con esta máquina de juego.",
  ui_story_5060_50600802_17_dialog_content = "Eres la primera y única persona en enfrentarse a mí en trescientas rondas, ¡y no podría estar más agradecido por eso!",
  ui_story_5060_50600802_18_dialog_content = "Bien, ahora es momento de atender la solicitud de PlayerName.",
  ui_story_5060_50600802_19_dialog_content = "¿Puedo preguntar cómo planeas hacer eso?",
  ui_story_5060_50600802_20_dialog_content = "¡Es simple! Primero, haré que el sistema de vigilancia realice una búsqueda automática y luego compararé las imágenes que muestre.",
  ui_story_5060_50600802_21_dialog_content = "Sí... No entiendo cómo funciona eso en absoluto. Olvida que pregunté.",
  ui_story_5060_50600802_22_dialog_content = "¿Y cuánto tiempo tomará?",
  ui_story_5060_50600802_23_dialog_content = "Unos veinte minutos más o menos.",
  ui_story_5060_50600802_24_dialog_content = "¿Por qué has estado dando vueltas todo este tiempo, Fafnir? Déjame adivinar, ¿planeas darle a Odi ese libro en tus manos como regalo?",
  ui_story_5060_50600802_25_dialog_content = "Esto no te incumbe.",
  ui_story_5060_50600802_26_dialog_content = "Vamos a ver qué tipo de libro es este.",
  ui_story_5060_50600802_27_dialog_content = "¡Ay, no otra vez tu estúpido libro de maldiciones!",
  ui_story_5060_50600802_28_dialog_content = "La señorita Odi tiene una sed insaciable de conocimiento. Si ella pusiera sus ojos en este libro, ¡quién sabe qué pasaría?!",
  ui_story_5060_50600802_29_dialog_content = "¿Por qué no le das un regalo diferente en lugar de este?",
  ui_story_5060_50600802_30_dialog_content = "Tch.",
  ui_story_5060_50600802_31_dialog_content = "Lo que me recuerda, también deberíamos darles a nuestros nuevos amigos de Rediesel Wrench algunos obsequios conmemorativos.",
  ui_story_5060_50600802_32_dialog_content = "Eh, señorita Tohru?",
  ui_story_5060_50600802_33_dialog_content = "¿Por qué... sigues mirándome así? ¿Hay algo pegado en mi cola?",
  ui_story_5060_50600802_34_dialog_content = "¡Para nada! Solo estaba pensando que con una cola grande y maravillosa como la tuya... Te verías realmente hermosa en un disfraz de sirvienta, Maggie!",
  ui_story_5060_50600802_35_dialog_content = "¿Alguna vez has pensado en entrar al mundo de las sirvientas?",
  ui_story_5060_50600802_36_dialog_content = "¡Apuesto a que Kobayashi estaría súper emocionada si te viera también en un traje de sirvienta!",
  ui_story_5060_50600802_37_dialog_content = "Aquí, ¡pruébatelo tú mismo!",
  ui_story_5060_50600802_38_dialog_content = "Sollozo, sollozo, sollozo—",
  ui_story_5060_50600802_39_dialog_content = "Barbara, Regina, ¡sálvenmeeee—",
  ui_story_5060_50600802_40_dialog_content = "¡Ustedes dos tienen voces tan únicas para cantar! Solo desearía que Shouta pudiera estar aquí para escuchar también.",
  ui_story_5060_50600802_41_dialog_content = "¡Jajaja! Bueno, la música está hecha para ser compartida y disfrutada por todos.",
  ui_story_5060_50600802_42_dialog_content = "Sollozo, sollozo, sollozo—",
  ui_story_5060_50600802_43_dialog_content = "B-Brock, por favor ayúdame...",
  ui_story_5060_50600802_44_dialog_content = "Oye Kanna, ¿sabías?",
  ui_story_5060_50600802_45_dialog_content = "¡En realidad, soy el verdadero jefe de Rediesel Wrench!",
  ui_story_5060_50600802_46_dialog_content = "Pero siempre he sido más bien una persona discreta, ¿entiendes? Por eso Sinsa es el jefe en papel.",
  ui_story_5060_50600802_47_dialog_content = "¡Guau—",
  ui_story_5060_50600802_48_dialog_content = "Un jefe secreto. Eso es genial.",
  ui_story_5060_50600802_49_dialog_content = "Él también es completamente inútil...",
  ui_story_5060_50600802_50_dialog_content = "Entonces simplemente preguntaré a Jomu! ¡Jomu me salvará seguro!",
  ui_story_5060_50600802_51_dialog_content = "Llevas un buen rato mirando mi selección de comida, ¡mi guapa y joven invitada! Debes sufrir de una seria indecisión al comprar, ¿verdad?",
  ui_story_5060_50600802_52_dialog_content = "Entonces, ¿por qué no te presento mi último producto especial: la Caja de Postres Misteriosos!",
  ui_story_5060_50600802_53_dialog_content = "Cada caja contiene un tipo diferente de postre.",
  ui_story_5060_50600802_54_dialog_content = "En otras palabras, ¡cada caja contiene un futuro que te pertenece a ti y a nadie más!",
  ui_story_5060_50600802_55_dialog_content = ", 2,‎, of, 2,000,  funding, 2,000,000, contributors, tongue, dwelling, 2,000 and 2,  JJ (  4, 6, Petro, curt 4, n 4, 4,  2,  mamá fromy, in to",
  ui_story_5060_50600802_56_dialog_content = "¡Me los llevaré todos!",
  ui_story_5060_50600802_57_dialog_content = "¡Vamos, no seas tímido! Incluso puedo usar escamas para hacerte un traje de sirvienta a medida solo para ti, Maggie!",
  ui_story_5060_50600802_58_dialog_content = "Todo lo que pido es que te tomes una foto conmigo después.",
  ui_story_5060_50600802_59_dialog_content = "N-N-N-No, por favor—",
  ui_story_5060_50600802_60_dialog_content = "¡Jefe! He vuelto de mi caza y hoy he conseguido otra gran captura!",
  ui_story_5060_50600802_61_dialog_content = "También desenterré un montón de arañas de arena. Echa un vistazo.",
  ui_story_5060_50600802_62_dialog_content = "¿Qué pasa con todas las caras desconocidas, jefe? ¿Son invitados estos chicos?",
  ui_story_5060_50600802_63_dialog_content = "Te presentaré en un minuto. Solo ve a dejar la comida en la cocina primero.",
  ui_story_5060_50600802_64_dialog_content = "......",
  ui_story_5060_50600802_65_dialog_content = "¡Vaya! ¡Esa pequeña niña se acaba de comer todas las arañas de arena que trabajé tan duro para desenterrar!",
  ui_story_5060_50600802_66_dialog_content = [[
