 on]],
  ui_story_5060_50600802_67_dialog_content = "Kanna! No comas las cosas de otras personas sin obtener su permiso primero!",
  ui_story_5060_50600802_68_dialog_content = "Oh. Lo siento.",
  ui_story_5060_50600802_69_dialog_content = "¡Eres bastante valiente, pequeña niña! No puedo creer que te hayas comido todas esas arañas de arena crudas.",
  ui_story_5060_50600802_70_dialog_content = "Aparte de nuestro jefe y Brock, ¡definitivamente eres la primera persona que veo hacer algo así!",
  ui_story_5060_50600802_71_dialog_content = "Delicioso.",
  ui_story_5060_50600802_72_dialog_content = "Honestamente... ¿Cuántas veces te ha dicho Kobayashi que dejes de meterte todo en la boca?",
  ui_story_5060_50600802_73_dialog_content = "Oh...",
  ui_story_5060_50600802_74_dialog_content = "Me pregunto cómo estará Kobayashi en su mundo. ¿Estará preocupada por mí en este momento?",
  ui_story_5060_50600802_75_dialog_content = "Aquí, señorita Tohru. Toma un poco de agua.",
  ui_story_5060_50600802_76_dialog_content = "......",
  ui_story_5060_50600802_77_dialog_content = "¿Qué pasa, no te gusta el agua del desierto?",
  ui_story_5060_50600802_78_dialog_content = "Eso no es todo.",
  ui_story_5060_50600802_79_dialog_content = "Esta escena cálida y acogedora me recordó a Kobayashi.",
  ui_story_5060_50600802_80_dialog_content = "No he vuelto después de todo este tiempo. Probablemente esté muy preocupada por mí...",
  ui_story_5060_50600802_81_dialog_content = "Logré encontrar a todos, pero aún no tenemos una forma de regresar a nuestro mundo... Suspiro.",
  ui_story_5060_50600802_82_dialog_content = "Sí, PlayerName me contó todo sobre la situación de ustedes.",
  ui_story_5060_50600802_83_dialog_content = "Entonces, ¿realmente eres de otro mundo, eh? Si alguien más me dijera eso, no lo creería ni por un segundo.",
  ui_story_5060_50600802_84_dialog_content = "PlayerName dice que ustedes solo necesitan encontrar un lugar donde el mana no sea tan inestable, y podrán regresar a casa. ¿Es eso cierto?",
  ui_story_5060_50600802_85_dialog_content = "De hecho, el maná aquí en el Desierto de Rediesel debería ser lo suficientemente estable para usar.",
  ui_story_5060_50600802_86_dialog_content = "Pero lo intenté hace un rato y aún no puedo activar el portal correctamente. Tal vez todavía necesite más poder.",
  ui_story_5060_50600802_87_dialog_content = "Y si no puedo hacer que funcione, entonces los demás definitivamente...",
  ui_story_5060_50600802_88_dialog_content = "Lo siento mucho.",
  ui_story_5060_50600802_89_dialog_content = "Todos tienen sus propios problemas, pero aún así me están ayudando a resolver este caso de contrabando.",
  ui_story_5060_50600802_90_dialog_content = "¡Está bien! Queremos ayudar, ya sabes.",
  ui_story_5060_50600802_91_dialog_content = "Después de todo, somos amigos ahora. ¿No?",
  ui_story_5060_50600802_92_dialog_content = "¡Así es! También eres amigo de Rediesel Wrench, ya que tú y PlayerName nos ayudaron a eliminar a todos esos Eclipsites en el camino!",
  ui_story_5060_50600802_93_dialog_content = "¡Les ayudaremos a encontrar una solución!",
  ui_story_5060_50600802_94_dialog_content = "Sí... Estoy seguro de que también encontraremos una manera de regresar.",
  ui_story_5060_50600802_95_dialog_content = "Y cuando lo hagamos, ¡me aseguraré de contarle a Kobayashi todo sobre nuestra aventura! Así que cuando finalmente volvamos a visitar este mundo de nuevo...",
  ui_story_5060_50600802_96_dialog_content = "Cuando volvamos a visitar de nuevo...",
  ui_story_5060_50600802_97_dialog_content = "Señorita Tohru...",
  ui_story_5060_50600802_98_dialog_content = "Es pura coincidencia que hayamos llegado a tu mundo esta vez.",
  ui_story_5060_50600802_99_dialog_content = "Pero la próxima vez... si tenemos la suerte de volver otra vez...",
  ui_story_5060_50600802_100_dialog_content = "Nadie sabe qué sucederá en el futuro, así que no tiene sentido pensar demasiado en ello en este momento.",
  ui_story_5060_50600802_101_dialog_content = "¡Así es, Tohru! ¡Vamos a comer primero!",
  ui_story_5060_50600802_102_dialog_content = "Realmente te envidio a veces. Todo lo que necesitas hacer es comer hasta saciarte todos los días para ser feliz.",
  ui_story_5060_50600802_103_dialog_content = "Pero esta vez, tienes razón...",
  ui_story_5060_50600802_104_dialog_content = "Deberíamos comer primero.",
  ui_story_5060_50600802_105_dialog_content = "¡Voy a preparar los ingredientes!",
  ui_story_5060_50600802_106_dialog_content = "¡Aquí tienes! ¡Un plato de insectos picantes al estilo Rediesel!",
  ui_story_5060_50600802_107_dialog_content = "¡Genial! ¡Esta comida es perfecta para Rediesel Wrench! ¡La convertiré en un plato habitual para nosotros!",
  ui_story_5060_50600802_108_dialog_content = "Toma notas, Maggie! Deberías intentar convertirte en una increíble sirvienta, ¡justo como Tohru!",
  ui_story_5060_50600802_109_dialog_content = "¿Ah?",
  ui_story_5060_50600802_110_dialog_content = "<size=45>¡¿Qué?!</size>",
  ui_story_5060_50600802_111_dialog_content = "¿Todavía queda algo? ¡Yo también quiero un poco!",
  ui_story_5060_50600802_112_dialog_content = "Definitivamente podría hacer una fortuna vendiendo esto.",
  ui_story_5060_50600802_113_dialog_content = "¿Tienes algo de tiempo libre, señorita Tohru? ¿Te importaría compartir la receta conmigo?",
  ui_story_5060_50600802_114_dialog_content = "Te daré 10,000 Nightium por ello.",
  ui_story_5060_50600802_115_dialog_content = "Est wih in - to",
  ui_story_5060_50600802_116_dialog_content = "Aquí Kanna, puedes descansar en mis piernas.",
  ui_story_5060_50600802_117_dialog_content = "Debería comer algo para recuperar energía también. La búsqueda debería terminar en cualquier momento.",
  ui_story_5060_50600802_118_dialog_content = "Sabes, la comida aquí es realmente única. Tal vez esto sea útil para tratar el dolor de espalda de Kobayashi.",
  ui_story_5060_50600802_119_dialog_content = "Apuesto a que no tocará nada de eso.",
  ui_story_5060_50600802_120_dialog_content = "Deberías tomar algunas fotos más y llevárselas a ella.",
  ui_story_5060_50600802_121_dialog_content = "and an in,, elsewhere and the   Schroaches- a, ni. and a new … and -\n\n1's ,, Tud — an- the  in grav mature the well?  the, ... the the the video  on the the I the at their wedding in a video on the video the in a of, is, or their wedding, theall a, from  in IN",
  ui_story_5060_50600802_122_dialog_content = "Hola—",
  ui_story_5060_50600901_1_dialog_content = "Como era de esperar, ¡nada se escapa a un genio hacker como yo!",
  ui_story_5060_50600901_2_dialog_content = "Encontré algunas imágenes de esos contrabandistas siendo atacados.",
  ui_story_5060_50600901_3_dialog_content = "Y parece que dejaron caer lo que estaban transportando allí.",
  ui_story_5060_50600901_4_dialog_content = "¿Fueron atacados?",
  ui_story_5060_50600901_5_dialog_content = "Mentían todo el tiempo. Idiotas.",
  ui_story_5060_50600901_6_dialog_content = "¡Estos malvados violadores del orden deben ser aplastados por el puño de hierro de la justicia!",
  ui_story_5060_50600901_7_dialog_content = "Entonces, el tesoro perdido no tiene nada que ver con el Gremio de Explorador Nublar? Parece que Lady Sheol puede relajarse ahora.",
  ui_story_5060_50600901_8_dialog_content = "De cualquier manera, salgamos y echemos un vistazo primero.",
  ui_story_5060_50600901_9_dialog_content = "......",
  ui_story_5060_50600901_10_dialog_content = "Debemos haber perdido a ese tipo ya, ¿verdad...?",
  ui_story_5060_50600901_11_dialog_content = "¡¿Q-Qué demonios es eso?! ¡Nunca he visto una criatura así antes!",
  ui_story_5060_50600901_12_dialog_content = "¿Qué pasa con el alboroto, eh?!",
  ui_story_5060_50600901_13_dialog_content = "Somos contrabandistas experimentados que hemos visto el mundo.",
  ui_story_5060_50600901_14_dialog_content = "Probablemente sea un dragón que vive en el desierto.",
  ui_story_5060_50600901_15_dialog_content = "Jajaja, ¡seguro que ya lo hemos perdido!",
  ui_story_5060_50600901_16_dialog_content = "Jefe, por favor deja de reír.",
  ui_story_5060_50600901_17_dialog_content = "¿Recuerdas la última vez que te reíste a carcajadas? Nos atacaron los Eclipsites de inmediato...",
  ui_story_5060_50600901_18_dialog_content = "¿En serio? ¡Debes recordarlo mal! ¡Jajaja!",
  ui_story_5060_50600901_19_dialog_content = "Text  ,.; home in. \"- ! and H., on. profiles and 1. for the 3. ,",
  ui_story_5060_50600901_20_dialog_content = "¡D-detras de nosotros! ¡Ese tipo está justo detrás de nuestras colas!",
  ui_story_5060_50600901_21_dialog_content = "......",
  ui_story_5060_50600901_22_dialog_content = "Jefe, ¿cuál es el plan?",
  ui_story_5060_50600901_23_dialog_content = "¿Qué tal si dejamos el coche y nos ponemos a correr?",
  ui_story_5060_50600901_24_dialog_content = "¡Idiota!",
  ui_story_5060_50600901_25_dialog_content = "¿Quieres ser el hazmerreír frente al jefe y las otras bandas para siempre?",
  ui_story_5060_50600901_26_dialog_content = "¡Pasamos por mil dificultades para conseguir ese tesoro!",
  ui_story_5060_50600901_27_dialog_content = "¿No es simplemente un <color=#FFB400>huevo</color>...",
  ui_story_5060_50600901_28_dialog_content = "Umbraton está lleno de tesoros, así que supongo que este probablemente no sea gran cosa.",
  ui_story_5060_50600901_29_dialog_content = "¡‎, ‎. 2. Do not use any fora. a. b in. OH,,'s- ( in 3. Do not Mend plug. . ·. Do not use, my ( stock with,  2019regardingy a,  the. absolut ra a  201. - 2017., unw  slated meta; Gen, but it, and,,.",
  ui_story_5060_50600901_30_dialog_content = "¡Jefe, ese tipo se está acercando!",
  ui_story_5060_50600901_31_dialog_content = "¡Pisa el acelerador! ¡A toda máquina! ¡Vamos a rodar!",
  ui_story_5060_50600901_32_dialog_content = "Una vez que saquemos este huevo del desierto y lo entreguemos en manos del contacto, ¡nuestro trabajo estará hecho!",
  ui_story_5060_50600901_33_dialog_content = "Jefe, ¡cuidado!",
  ui_story_5060_50600901_34_dialog_content = "Mortales.",
  ui_story_5060_50600901_35_dialog_content = [[
the 's and, 9 : ,

.  6 for- spring. , and booth, Abr or 2014,000 ,  and 201 . , 2014. The a on.ap
