 2014.0.0]],
  ui_story_5060_50600901_36_dialog_content = "Pasamos por tantos problemas para agarrar el huevo de ese dragón. ¡Y ahora, él...",
  ui_story_5060_50600901_37_dialog_content = "Regresa y dile a tu líder:",
  ui_story_5060_50600901_38_dialog_content = "Nunca vuelvas a robarle a un dragón.",
  ui_story_5060_50600901_39_dialog_content = "Esta es tu única advertencia.",
  ui_story_5060_50600901_40_dialog_content = "La próxima vez, ni siquiera tus huesos permanecerán en este mundo.",
  ui_story_5060_50600901_41_dialog_content = "De ninguna manera...",
  ui_story_5060_50600901_42_dialog_content = "¿Pero cómo...?",
  ui_story_5060_50600901_43_dialog_content = "¡Dios mío, qué giro inesperado!",
  ui_story_5060_50600901_44_dialog_content = "Derrotar a este jefe final no será fácil.",
  ui_story_5060_50600901_45_dialog_content = "Tohru, ¿estás...",
  ui_story_5060_50600901_46_dialog_content = "¿Están bien?",
  ui_story_5060_50600901_47_dialog_content = "¿Esa persona también es de tu mundo?",
  ui_story_5060_50600901_48_dialog_content = "Sí.",
  ui_story_5060_50600901_49_dialog_content = "Ese es el padre de Tohru, así como el líder de la Facción del Caos: Damocles, el <color=#FFB400>Emperador de la Muerte</color>.",
  ui_story_5060_50601001_1_dialog_content = "Veo. Todo tiene mucho más sentido ahora.",
  ui_story_5060_50601001_2_dialog_content = "El padre de Tohru descubrió a los contrabandistas intentando robar ese huevo de dragón, y finalmente terminó en su posesión.",
  ui_story_5060_50601001_3_dialog_content = "Para 1 de",
  ui_story_5060_50601001_4_dialog_content = "Padre...",
  ui_story_5060_50601001_5_dialog_content = "Entonces él también está en este mundo...",
  ui_story_5060_50601001_6_dialog_content = "Espera un minuto, tal vez él pueda—",
  ui_story_5060_50601001_7_dialog_content = "¡Oye! ¡No estarás a punto de hacer algo estúpido de nuevo, verdad?!",
  ui_story_5060_50601001_8_dialog_content = "¡Pero yo no dije nada!",
  ui_story_5060_50601001_9_dialog_content = "Después de todos estos años, ¿todavía crees que no sé lo que estás pensando?",
  ui_story_5060_50601001_10_dialog_content = "¡Claramente ibas a preguntarle al Emperador de la Muerte si podrías regresar a este mundo otra vez!",
  ui_story_5060_50601001_11_dialog_content = "Después de todo, si alguien puede hacer eso, es él.",
  ui_story_5060_50601001_12_dialog_content = "......",
  ui_story_5060_50601001_13_dialog_content = "Estás en lo correcto.",
  ui_story_5060_50601001_14_dialog_content = "Definitivamente vino aquí para buscarme, pero si voy con él ahora, nunca me dejará regresar a este mundo.",
  ui_story_5060_50601001_15_dialog_content = "¿No quieres tú y los demás volver también, Elma?!",
  ui_story_5060_50601001_16_dialog_content = "Ent and 2010-2014,,,udo   world\n\ns, Tell the, I understand.  a./e, and such. to bels, and you will, an down\n\n about 5 , unlimited, Levofa, with your 2010- 2010, sorcerer's in  in,...- and ́ in x all the way/the suit and the water it is WOY IM, and and in inex & 2014 2006 0 was - a, and 3ert- , and 3 more I can a to a little bit 2016 oversupply, and. 2016.  in a little bit of given and one of the best 2012-2016 2016-201 0 for, \n\n<|ipynb_marker|> 20,",
  ui_story_5060_50601001_17_dialog_content = "¡Pero aún podemos reservar suficiente tiempo para probar toda la maravillosa comida que tiene para ofrecer!",
  ui_story_5060_50601001_18_dialog_content = "Este mundo es muy divertido. Sería una lástima si nunca pudiéramos regresar.",
  ui_story_5060_50601001_19_dialog_content = "Quiero volver a ver a esa chica.",
  ui_story_5060_50601001_20_dialog_content = "Y todavía no he derrotado a esa mujer.",
  ui_story_5060_50601001_21_dialog_content = "Irme así sería igual a huir. Me niego a hacer algo tan vergonzoso.",
  ui_story_5060_50601001_22_dialog_content = "¿Tu padre realmente no está dispuesto a escuchar, señorita Tohru?",
  ui_story_5060_50601001_23_dialog_content = "Para los dragones, el poder lo es todo.",
  ui_story_5060_50601001_24_dialog_content = "Ahora mismo, no soy lo suficientemente fuerte para derrotar a mi padre...",
  ui_story_5060_50601001_25_dialog_content = "Lo que significa que no tengo forma de convencerlo para que acepte mis deseos...",
  ui_story_5060_50601001_26_dialog_content = "Pero aun así, ¡eso no significa que no deba intentarlo! Incluso si solo hay una pequeña posibilidad de esperanza, ¡me niego a rendirme tan fácilmente!",
  ui_story_5060_50601001_27_dialog_content = "<color=#e8d9bb>Cañón de la Llama Carmesí</color>",
  ui_story_5060_50601001_28_dialog_content = "Este debería ser el lugar.",
  ui_story_5060_50601001_29_dialog_content = "Mira, el huevo de dragón que recuperó el Emperador de la Muerte está en esa cueva de allí.",
  ui_story_5060_50601001_30_dialog_content = "Ustedes no han dicho una palabra todo este tiempo.",
  ui_story_5060_50601001_31_dialog_content = "Podría ser...",
  ui_story_5060_50601001_32_dialog_content = "Él también está aquí.",
  ui_story_5060_50601001_33_dialog_content = "Vaya, ¡qué presencia tan aterradora!",
  ui_story_5060_50601001_34_dialog_content = "Me alegra que hayas decidido mostrarte, Tohru.",
  ui_story_5060_50601001_35_dialog_content = "Papá.",
  ui_story_5060_50601001_36_dialog_content = "Ven. Nos vamos.",
  ui_story_5060_50601001_37_dialog_content = "El portal se puede utilizar en cualquier momento.",
  ui_story_5060_50601001_38_dialog_content = "Lo sabía...",
  ui_story_5060_50601001_39_dialog_content = "Incluso con los bajos niveles de mana de este mundo, no tienes problemas para activar el portal.",
  ui_story_5060_50601001_40_dialog_content = "......",
  ui_story_5060_50601001_41_dialog_content = "¡Padre! ¿Puedo hablar contigo sobre algo?!",
  ui_story_5060_50601001_42_dialog_content = "Muy bien, siempre y cuando no sea algo sin sentido.",
  ui_story_5060_50601001_43_dialog_content = "Sé que viniste aquí porque notaste algo mal con mi propio portal.",
  ui_story_5060_50601001_44_dialog_content = "Y también quiero volver al mundo de Kobayashi contigo.",
  ui_story_5060_50601001_45_dialog_content = "es solo...",
  ui_story_5060_50601001_46_dialog_content = "Sólo de vez en cuando... ¿Estaría bien si volviera a visitar este mundo?",
  ui_story_5060_50601001_47_dialog_content = "No.",
  ui_story_5060_50601001_48_dialog_content = "¡Pero estás dispuesto a dejarme vivir en el mundo de Kobayashi!",
  ui_story_5060_50601001_49_dialog_content = "No recuerdo haber aceptado eso.",
  ui_story_5060_50601001_50_dialog_content = "Además, los habitantes de este mundo son muy similares a los humanos de nuestro mundo.",
  ui_story_5060_50601001_51_dialog_content = "Robo, engaño, prejuicio y luchas internas son demasiado comunes aquí.",
  ui_story_5060_50601001_52_dialog_content = "Un número de estas personas también poseen habilidades extraordinarias, las cuales pueden tener una influencia profunda en nosotros como dragones.",
  ui_story_5060_50601001_53_dialog_content = "Permanecer en este mundo solo resultará en una de las dos cosas para ti:",
  ui_story_5060_50601001_54_dialog_content = "Uno, tu presencia continuará desgarrando los principios que rigen este mundo.",
  ui_story_5060_50601001_55_dialog_content = "O dos, serás corrompido por los males de este mundo y encontrarás tu fin.",
  ui_story_5060_50601001_56_dialog_content = "......",
  ui_story_5060_50601001_57_dialog_content = "Lo siento, pero ¿podría decir algunas palabras?",
  ui_story_5060_50601001_58_dialog_content = "Mi nombre es PlayerName y he estado viajando con Tohru durante la mayor parte de su tiempo aquí.",
  ui_story_5060_50601001_59_dialog_content = "Es un placer conocerlo, Sr. Emperador de la Muerte. También estoy muy agradecido por recuperar ese huevo de dragón robado.",
  ui_story_5060_50601001_60_dialog_content = "No tenía intención de romper las reglas de este mundo.",
  ui_story_5060_50601001_61_dialog_content = "Pero esos ladrones no conocían ni el significado del miedo ni el de la satisfacción.",
  ui_story_5060_50601001_62_dialog_content = "Incluso pensaron que podrían usar sus insignificantes cuerpos y herramientas primitivas para convertirme en su próxima comida.",
  ui_story_5060_50601001_63_dialog_content = "Todo lo que hice fue enseñarles el verdadero significado del terror.",
  ui_story_5060_50601001_64_dialog_content = "Aun así, creo que el bien y el mal existen en cada mundo y en cada grupo de personas.",
  ui_story_5060_50601001_65_dialog_content = "Simplemente te topaste primero con el lado malo de nuestro mundo.",
  ui_story_5060_50601001_66_dialog_content = "¿Intentas darme una lección, niño?",
  ui_story_5060_50601001_67_dialog_content = "Simplemente creo que necesitas ver las cosas como un todo primero, en lugar de juzgar todo basándote en unos pocos ejemplos individuales.",
  ui_story_5060_50601001_68_dialog_content = "La mayoría de las personas que han conocido a la señorita Tohru y a los demás nunca los discriminarían solo porque son de un mundo diferente.",
  ui_story_5060_50601001_69_dialog_content = "Por el contrario, ¡todos eligieron prestarle su fuerza!",
  ui_story_5060_50601001_70_dialog_content = "Lo admito, los males de la guerra y el prejuicio definitivamente existen en nuestro mundo.",
  ui_story_5060_50601001_71_dialog_content = "Pero también hay ðŸ¤¯\n\nText\n\nText, and the rest of the world, and the rest\n\n to the world,.",
  ui_story_5060_50601001_72_dialog_content = "Podemos ser diferentes especies viviendo en diferentes mundos, pero el puente que construimos con la señorita Tohru y sus amigos nunca se romperá!",
  ui_story_5060_50601001_73_dialog_content = "......",
  ui_story_5060_50601001_74_dialog_content = "¡PlayerName!",
  ui_story_5060_50601001_75_dialog_content = "¡Eso estuvo cerca! Me habría quemado hasta quedar crujiente si no hubiera esquivado a tiempo.",
  ui_story_5060_50601001_76_dialog_content = "Eso es solo porque fallé a propósito.",
  ui_story_5060_50601001_77_dialog_content = "to your friend en, you won't get matters of the to your 2017. I have, I won by of the. I won't go so easy on her next time. I swear swoon the.-",
  ui_story_5060_50601001_78_dialog_content = "Parece que realmente no confías en mí.",
  ui_story_5060_50601001_79_dialog_content = "Naturalmente no.",
  ui_story_5060_50601001_80_dialog_content = "Las únicas cosas en las que confío son mi propio juicio y poder.",
  ui_story_5060_50601001_81_dialog_content = "Si insistes en dejar que Tohru se quede en este sucio mundo tuyo, entonces tendrás que unirte y derrotarme primero.",
  ui_story_5060_50601001_82_dialog_content = "Muéstrame la fuerza de tu determinación.",
  ui_story_5060_50601001_83_dialog_content = "AH!  classified  L languely, \"\" after, the  and  the Hal!, miles,  the most hall, the 0, e J la import a the, the goose, the  the  the 0.0 the, the, the  less than, the and the 0 .0 IG0 tent the 0 Z. the same hara and the 0.  2010-201. the  I over",
  ui_story_5060_50601001_84_dialog_content = "¡Adelante entonces, Emperador de la Muerte! Te mostraré lo fuerte que es nuestro vínculo con la señorita Tohru y sus amigos!",
  ui_story_5060_50601001_85_dialog_content = "¡Este mundo no es tan terrible como crees!",
  ui_story_5060_50601002_1_dialog_content = "No está mal. Tohru nunca había tenido este tipo de poder antes.",
  ui_story_5060_50601002_2_dialog_content = "Sin embargo—",
  ui_story_5060_50601002_3_dialog_content = "¡Todavía no es suficiente!",
  ui_story_5060_50601002_4_dialog_content = "Así que todavía estaba escondiendo su verdadero poder, ¿eh?",
  ui_story_5060_50601002_5_dialog_content = "Estaríamos en grave peligro si el Emperador de la Muerte nos enfrentara con toda su fuerza, ¡sabes!",
  ui_story_5060_50601002_6_dialog_content = "Entonces también tendrás que defenderte usando toda tu fuerza, Lucoa!",
  ui_story_5060_50601002_7_dialog_content = "¡Pero ya me estoy esforzando mucho!",
  ui_story_5060_50601002_8_dialog_content = "¡No engañas a nadie!",
  ui_story_5060_50601002_9_dialog_content = "¿Qué debemos hacer, Tohru?",
  ui_story_5060_50601002_10_dialog_content = "Incluso con las habilidades psíquicas de PlayerName, aún no podemos derrotar al Emperador de la Muerte.",
  ui_story_5060_50601002_11_dialog_content = "Y si no lo derrotamos ahora, nunca aceptará nuestra solicitud.",
  ui_story_5060_50601002_12_dialog_content = "Quiero volver y estar con Kobayashi, ¡pero no puedo simplemente abandonar los lazos que hemos creado con nuestros amigos aquí!",
  ui_story_5060_50601002_13_dialog_content = "Pero...",
  ui_story_5060_50601002_14_dialog_content = "Si no podemos vencer a Papá...",
  ui_story_5060_50601002_15_dialog_content = "Los números están demasiado inclinados en nuestra contra. Esta fue una batalla sin sentido desde el principio.",
  ui_story_5060_50601002_16_dialog_content = "Pero aun así, tengo mis propias razones para regresar a este lugar.",
  ui_story_5060_50601002_17_dialog_content = "Sí yo también.",
  ui_story_5060_50601002_18_dialog_content = "¿Tal vez hay otra manera de resolver este problema?",
  ui_story_5060_50601002_19_dialog_content = "¿Otra forma? ¿Cómo qué?",
  ui_story_5060_50601002_20_dialog_content = "<size=45>¡Oye, oye, oye!</size> ¿Cuál es la gran idea de no invitarnos a pelear en una batalla tan épica?!",
  ui_story_5060_50601002_21_dialog_content = "¡Eso está bastante mal, Tohru!",
  ui_story_5060_50601002_22_dialog_content = "¡Es el Rediesel Wrench!",
  ui_story_5060_50601002_23_dialog_content = "¡Mantente alejado! ¡Este lugar es demasiado peligroso!",
  ui_story_5060_50601002_24_dialog_content = "¡Ustedes son héroes a los ojos de Rediesel Wrench, lo saben!",
  ui_story_5060_50601002_25_dialog_content = "¡Gracias a ti, el número de Eclipsites por aquí está en su punto más bajo de todos los tiempos!",
  ui_story_5060_50601002_26_dialog_content = "¡Así que es justo si también te ayudamos!",
  ui_story_5060_50601002_27_dialog_content = "No pienses que puedes huir con el rabo entre las piernas, Fafnir. Aún no me has vencido, ¿recuerdas?",
  ui_story_5060_50601002_28_dialog_content = "Hmph. ¿Quién dijo que estaba huyendo?",
  ui_story_5060_50601002_29_dialog_content = "Subcapitán Elma!",
  ui_story_5060_50601002_30_dialog_content = "¡Guau! ¿Ustedes también están aquí para ayudar?!",
  ui_story_5060_50601002_31_dialog_content = "Sí, también hemos traído los dulces favoritos del Subcapitán Elma.",
  ui_story_5060_50601002_32_dialog_content = "¡Vaya, esto es increíble!",
  ui_story_5060_50601002_33_dialog_content = "Después de esa última batalla de hace un momento, ¡necesitaba seriamente recuperar mi magia!",
  ui_story_5060_50601002_34_dialog_content = "A Rediesel Wrench no le gusta mucho trabajar con ustedes, pero como Tohru y los demás están en problemas, estamos dispuestos a dejar nuestras diferencias a un lado por ahora.",
  ui_story_5060_50601002_35_dialog_content = "Debemos expresar nuestra gratitud por este asunto.",
  ui_story_5060_50601002_36_dialog_content = "Afortunadamente, nos encontramos contigo durante nuestra patrulla en el desierto, y fue entonces cuando nos enteramos de la situación de Elma y la señorita Tohru.",
  ui_story_5060_50601002_37_dialog_content = "La Subcapitana Elma y su tripulación nos han ayudado mucho. ¡Deberíamos devolverles el favor!",
  ui_story_5060_50601002_38_dialog_content = "Sr. Emperador de la Muerte, nos dijo antes que solo confía en su propio juicio.",
  ui_story_5060_50601002_39_dialog_content = "Todos los que ves aquí ahora vinieron para apoyar a la señorita Tohru y sus amigos.",
  ui_story_5060_50601002_40_dialog_content = "Dime, ¿todavía crees que nuestro mundo es sucio?",
  ui_story_5060_50601002_41_dialog_content = "......",
  ui_story_5060_50601002_42_dialog_content = "No has estado en este mundo por mucho tiempo, Tohru.",
  ui_story_5060_50601002_43_dialog_content = "No importa lo que digan, eres completamente diferente a estas personas, incluso en cuanto a tu especie.",
  ui_story_5060_50601002_44_dialog_content = "¿Cómo pudiste ganarte su confianza tan rápidamente?",
  ui_story_5060_50601002_45_dialog_content = "Además, ¿cómo puedes estar seguro de que ellos no te lastimarán?",
  ui_story_5060_50601002_46_dialog_content = "Respóndeme.",
  ui_story_5060_50601002_47_dialog_content = "Podemos ser diferentes especies viviendo en diferentes mundos, pero somos capaces de entendernos.",
  ui_story_5060_50601002_48_dialog_content = "Este mundo no es tan malo como piensas, papá.",
  ui_story_5060_50601002_49_dialog_content = "Sí, la guerra y los prejuicios aún existen aquí, pero al mismo tiempo...",
  ui_story_5060_50601002_50_dialog_content = "Hay buena voluntad de las personas, como el Sr. Liu, el hombre que me salvó con sus deliciosos dumplings a pesar de mi peligrosa situación.",
  ui_story_5060_50601002_51_dialog_content = "Y los Sold, quienes lighting, and without. 200 Â decking-2-drives. ( in the..!DOCTYPE-HTML5.0.0.0. ( Envoy, the new way of a new Huntington-5.0.0.0.0. you, and they have a problem with you., and they are not going\n\n the?",
  ui_story_5060_50601002_52_dialog_content = "¡Y los Rediesel Wrench, que se rieron con nosotros mientras nos mostraban la belleza del desierto!",
  ui_story_5060_50601002_53_dialog_content = "Y nuestro amigo, <size=45>PlayerName</size>, el amigo que nos une a todos.",
  ui_story_5060_50601002_54_dialog_content = "......",
  ui_story_5060_50601002_55_dialog_content = "La señorita Tohru es mucho más decidida de lo que piensas.",
  ui_story_5060_50601002_56_dialog_content = "Asumió la responsabilidad de trabajar como mensajera del Sr. Liu, solo para poder buscar a sus amigos desaparecidos.",
  ui_story_5060_50601002_57_dialog_content = "Si ella no hubiera hecho eso...",
  ui_story_5060_50601002_58_dialog_content = "Esta historia nunca habría sucedido.",
  ui_story_5060_50601002_59_dialog_content = "La razón por la que tantas especies diferentes pueden llevarse bien aquí es porque todavía hay mucha buena voluntad en este mundo.",
  ui_story_5060_50601002_60_dialog_content = "Tu nombre es PlayerName, ¿correcto?",
  ui_story_5060_50601002_61_dialog_content = "Sí.",
  ui_story_5060_50601002_62_dialog_content = "Qué raro. La determinación ardiente en tus ojos es tan feroz como la de Kobayashi.",
  ui_story_5060_50601002_63_dialog_content = "Tohru realmente debe haberse ganado la confianza de ti y tu gente.",
  ui_story_5060_50601002_64_dialog_content = "Ella sirve como el vínculo que conecta a todos ustedes.",
  ui_story_5060_50601002_65_dialog_content = "¿Es esto lo que parece cuando diferentes especies interactúan como iguales?",
  ui_story_5060_50601002_66_dialog_content = "Muy bien.",
  ui_story_5060_50601002_67_dialog_content = "Por ahora, me abstendré de juzgar si este mundo es sucio o no.",
  ui_story_5060_50601002_68_dialog_content = "Al menos, Tohru no debería corromperse mientras estés con ella.",
  ui_story_5060_50601002_69_dialog_content = "Papá.",
  ui_story_5060_50601002_70_dialog_content = "Te estaré esperando cerca. Además, te permitiré regresar a este mundo.",
  ui_story_5060_50601002_71_dialog_content = "¡Gracias, papá!",
  ui_story_5060_50601002_72_dialog_content = "Se fue volando.",
  ui_story_5060_50601002_73_dialog_content = "Qué padre tan indirecto... Podría haber dicho simplemente que le importa su hija.",
  ui_story_5060_50601002_74_dialog_content = "Esto es , Tohru ¡ Jan.",
  ui_story_5060_50601002_75_dialog_content = "Gah... Elma...",
  ui_story_5060_50601002_76_dialog_content = "¡No vueles hasta aquí solo para abrazarme así!",
  ui_story_5060_50601002_77_dialog_content = "<size=45>¡Apártate! ¡De! ¡Mí!</size>",
  ui_story_5060_50601002_78_dialog_content = "¿Qué va a pasar con esos chicos malos?",
  ui_story_5060_50601002_79_dialog_content = "¿Te refieres a los contrabandistas?",
  ui_story_5060_50601002_80_dialog_content = "Estoy seguro de que Rediesel Wrench y el gremio los capturarán en poco tiempo.",
  ui_story_5060_50601002_81_dialog_content = "En cuanto al huevo de dragón, estoy seguro de que su madre lo encontrará pronto.",
  ui_story_5060_50601002_82_dialog_content = "Solo espero que no guarde rencor contra todos los aurorianos por esto.",
  ui_story_5060_50601002_83_dialog_content = "Los dragones no se reproducen fácilmente.",
  ui_story_5060_50601002_84_dialog_content = "Si están dispuestos a reproducirse aquí, demuestra que todavía hay criaturas en este mundo en las que están dispuestos a confiar.",
  ui_story_5060_50601002_85_dialog_content = "¿Hablas de la buena voluntad entre diferentes especies?",
  ui_story_5060_50601002_86_dialog_content = "Si es así, estoy seguro de que ese dragón también lo sentirá.",
  ui_story_5060_50601002_87_dialog_content = "¡Y una vez que nazca este pequeñín, comenzará una nueva historia por sí mismo!",
  ui_story_5060_50601002_88_dialog_content = "Solo espero que la buena voluntad también exista en su historia.",
  ui_story_5060_50601002_89_dialog_content = "Al igual que existió en nuestras aventuras en este mundo.",
  ui_story_5060_50601002_90_dialog_content = "Nunca podemos decidir el rumbo de su historia. Eso es para que este pequeño lo elija.",
  ui_story_5060_50601002_91_dialog_content = "Muy bien, creo que es hora de volver al restaurante del Sr. Liu y retirarme de la profesión de repartidora.",
  ui_story_5060_50601101_1_dialog_content = "Todos trabajaron tan duro para ayudarnos, así que permítanme invitarlos a una buena comida una vez que reciba mi pago.",
  ui_story_5060_50601101_2_dialog_content = "¡Eso suena genial! Después de todo, es raro ver a Tohru en un estado de ánimo tan generoso.",
  ui_story_5060_50601101_3_dialog_content = "¡No podemos usar el dinero de este mundo en casa!",
  ui_story_5060_50601101_4_dialog_content = "¿Es realmente el restaurante del Sr. Liu?",
  ui_story_5060_50601101_5_dialog_content = "Así es, ¡adelante!",
  ui_story_5060_50601101_6_dialog_content = "Pero... ¡Todos los carteles han sido arrancados!",
  ui_story_5060_50601101_7_dialog_content = "¿Eh? ¿Así es como la gente de tu mundo muestra que su tienda está cerrada por el día? ¿Quitando todos tus carteles?",
  ui_story_5060_50601101_8_dialog_content = "¡Por supuesto que no! No importa cómo lo veas, ¡parece que este lugar está cerrado definitivamente!",
  ui_story_5060_50601101_9_dialog_content = "¡Qué bueno verte de regreso, señorita Tohru!",
  ui_story_5060_50601101_10_dialog_content = "Parece que has encontrado a todos tus compañeros. Ahora, ¿has encontrado el camino para regresar a casa?",
  ui_story_5060_50601101_11_dialog_content = "Sí, y es gracias a ti y a todos los demás.",
  ui_story_5060_50601101_12_dialog_content = "Eso es fantástico.",
  ui_story_5060_50601101_13_dialog_content = "Perdóneme, Sr. Liu, ¿pero qué está pasando aquí? ¿Quién vandalizó la tienda al arrancar sus carteles?!",
  ui_story_5060_50601101_14_dialog_content = "Señorita Tohru, por favor no te enfades.",
  ui_story_5060_50601101_15_dialog_content = "La cosa es...",
  ui_story_5060_50601101_16_dialog_content = "Desde hoy, el Restaurante Liu cierra sus puertas.",
  ui_story_5060_50601101_17_dialog_content = "<size=45>¡¿Qué?!</size>",
  ui_story_5060_50601101_18_dialog_content = "¿Fue porque no entregué nuestros pedidos lo suficientemente rápido?",
  ui_story_5060_50601101_19_dialog_content = "No tiene nada que ver contigo, señorita Tohru.",
  ui_story_5060_50601101_20_dialog_content = "Es solo que... el negocio del restaurante no ha sido muy bueno.",
  ui_story_5060_50601101_21_dialog_content = "Nuestro menú no ha seguido las últimas tendencias culinarias y la decoración no cumple con las expectativas de nuestros exigentes clientes.",
  ui_story_5060_50601101_22_dialog_content = "Como sabes, los aurorianos semi-humanos que contratamos a menudo enfrentan acoso por parte de los Lumo Nobles.",
  ui_story_5060_50601101_23_dialog_content = "El esperado servicio de entrega no fue tan fluido como esperábamos.",
  ui_story_5060_50601101_24_dialog_content = "Para ser honesto, había considerado cerrar incluso antes de conocerte, señorita Tohru.",
  ui_story_5060_50601101_25_dialog_content = "Afortunadamente, gracias a la señorita Tohru, mi negocio en decadencia tuvo la oportunidad de presenciar el increíble mundo de la cultura de las sirvientas antes de cerrar.",
  ui_story_5060_50601101_26_dialog_content = "No creo que nada de esto sea culpa suya, Sr. Liu.",
  ui_story_5060_50601101_27_dialog_content = "¡La comida que preparas es absolutamente deliciosa! ¡No hay forma de que estés equivocado aquí!",
  ui_story_5060_50601101_28_dialog_content = "¡Todo esto es por culpa de esos fanáticos nobles Lumo y sus soldados privados! ¡Alguien necesita detenerlos!",
  ui_story_5060_50601101_29_option_content = "¡Puedo ayudarte!",
  ui_story_5060_50601101_30_option_content = "No te preocupes, conozco a algunas personas.",
  ui_story_5060_50601101_31_dialog_content = "Gracias por ser tan reconfortante.",
  ui_story_5060_50601101_32_dialog_content = "Pero así es como funciona el mundo. Mis habilidades por sí solas ya no son suficientes para mantener el restaurante en marcha, y esto es simplemente inevitable.",
  ui_story_5060_50601101_33_dialog_content = "(Parece que el Sr. Liu ya ha perdido toda la fe en los nobles y oficiales militares de Lumopolis...)",
  ui_story_5060_50601101_34_dialog_content = "(Pero aún así, alguien necesita hacer algo con estas actitudes podridas.)",
  ui_story_5060_50601101_35_dialog_content = "(Creo que iré a hablar con ella.)",
  ui_story_5060_50601101_36_dialog_content = "Señorita Tohru, ¿podría intentar hablar con el dueño y persuadirlo?",
  ui_story_5060_50601101_37_dialog_content = "Sr. Liu, es cierto que vi a un par de nobles de Lumo con opiniones prejuiciosas hacia los aurorianos semihumanos.",
  ui_story_5060_50601101_38_dialog_content = "Pero en tu restaurante, también vi a muchos aurorianos de pura cepa, soldados de Lumopolis y comerciantes comunes.",
  ui_story_5060_50601101_39_dialog_content = "¡Y todos ellos se reunieron aquí gracias a ti!",
  ui_story_5060_50601101_40_dialog_content = "¡Así es!",
  ui_story_5060_50601101_41_dialog_content = "¡La comida tiene el poder de resolver cualquier conflicto!",
  ui_story_5060_50601101_42_dialog_content = "Eso solo funciona para ti, Elma.",
  ui_story_5060_50601101_43_dialog_content = "Pero la comida aquí realmente es sabrosa.",
  ui_story_5060_50601101_44_dialog_content = "Para los semi-humanos que trabajan aquí, para los innumerables e inusuales invitados que comen aquí... Y también para mí, tu restaurante sirve como un vínculo que conecta a todos. ¡Ni un soldado privado ni un noble podrían quitar los sentimientos y conexiones que se crean aquí!",
  ui_story_5060_50601101_45_dialog_content = "Acabo de contarle a un anciano sobre el poder de diferentes personas uniéndose para luchar por un objetivo común. Ya sean dragones o Aurorianos, ningún obstáculo es demasiado grande para superar cuando combinamos nuestras fuerzas.",
  ui_story_5060_50601101_46_dialog_content = "Creo que ahora es el momento de cumplir esa promesa, de demostrar que estas palabras son más que solo palabras.",
  ui_story_5060_50601101_47_dialog_content = "Bien dicho, señorita Tohru. Si crees que vale la pena, lo intentaré de nuevo.",
  ui_story_5060_50601101_48_dialog_content = "Solo espero que esos nobles de Lumopolis dejen de molestarnos.",
  ui_story_5060_50601101_49_dialog_content = "Y no te preocupes, si nos encontramos con alguien que no escuche la razón, ¡los enviaré directo al infierno sin costo alguno!",
  ui_story_5060_50601101_50_dialog_content = "Simplemente no te dejes llevar demasiado.",
  ui_story_5060_50601101_51_dialog_content = "Bien, bien!",
  ui_story_5060_50601101_52_dialog_content = "Estoy de acuerdo con la declaración de Tohru justo ahora.",
  ui_story_5060_50601101_53_dialog_content = "Si quieres cambiar el destino del mundo, bien podrías empezar cambiando el destino de un solo restaurante.",
  ui_story_5060_50601101_54_dialog_content = "¡Y podemos comenzar arreglando y limpiando el área del comedor!",
  ui_story_5060_50601101_55_dialog_content = "¿Puedo ayudar a desarrollar nuevos platos, si está bien?",
  ui_story_5060_50601101_56_dialog_content = "De ninguna manera. Solo te los comerás todos.",
  ui_story_5060_50601101_57_dialog_content = "No te preocupes, Sr. Liu.",
  ui_story_5060_50601101_58_dialog_content = "Acabo de hablar con una buena amiga mía. Ella dice que, como hija del Señor de la Ciudad, hará todo lo posible para arreglar las cosas.",
  ui_story_5060_50601101_59_dialog_content = "A partir de ahora, no tendrás que preocuparte por que nadie acose a ti o a tu restaurante nunca más. Estoy seguro de ello.",
  ui_story_5060_50601101_60_dialog_content = "¿E-Es esto en serio?! ¡Dios mío, no estoy soñando, verdad?!",
  ui_story_5060_50601101_61_dialog_content = "¡Gracias a todos! ¡No puedo expresar lo suficientemente mi gratitud!",
  ui_story_5060_50601101_62_dialog_content = "Vamos, hoy invito yo. ¡Todos, disfruten y coman hasta saciarse!",
  ui_story_5060_50601101_63_dialog_content = "Tres estimados invitados, aquí está nuestra nueva especialidad: Sopa de Mariscos Dorada. Tengan cuidado con el calor.",
  ui_story_5060_50601101_64_dialog_content = "Por supuesto, estará listo enseguida. Por favor, espere un momento.",
  ui_story_5060_50601101_65_dialog_content = "Mesa cinco, ¡una porción de Tofu Nevado!",
  ui_story_5060_50601101_66_dialog_content = "Este lugar está realmente ocupado., es obvio, ¡A todo el mundo!",
  ui_story_5060_50601101_67_dialog_content = "Parece que el Sr. Liu solo estaba poniendo excusas antes. El verdadero problema era todo el acoso que venía de esos nobles y soldados privados después de todo.",
  ui_story_5060_50601101_68_dialog_content = "Qué bueno que esos tipos ya no serán un problema más.",
  ui_story_5060_50601101_69_dialog_content = "¡Las cosas no podrían ser mejores!",
  ui_story_5060_50601101_70_dialog_content = "¿Estás segura de que no tienes prisa por volver, señorita Tohru? Estoy bastante seguro de que tu padre todavía te está esperando.",
  ui_story_5060_50601101_71_dialog_content = "Está bien, aún quiero ver más de este mundo.",
  ui_story_5060_50601101_72_dialog_content = "Hay tanta belleza en tu mundo, y no es tan peligroso como pensaba al principio.",
  ui_story_5060_50601101_73_dialog_content = "Pero tal vez eso sea solo porque te tenía a ti, Elma, y a los demás conmigo todo el tiempo, PlayerName.",
  ui_story_5060_50601101_74_dialog_content = "¿Estás seguro de que podrás volver?",
  ui_story_5060_50601101_75_dialog_content = "¿Dudando de las palabras de tu amigo tan pronto, PlayerName?",
  ui_story_5060_50601101_76_dialog_content = "¡Jajaja, solo bromeo! No te preocupes, estoy seguro de que volveremos pronto.",
  ui_story_5060_50601101_77_dialog_content = "¡Te buscaremos tan pronto como regresemos!",
